"""Redaktionelle Aufgabenfamilien. Je Struktur zwei Varianten, nicht zwanzig Zahlenkopien.

SymPy ist nur ein Entwicklungswerkzeug. Die ausgelieferte App bleibt unabhängig
von Python, Paketen, Konten und Netzwerkdiensten.
"""
import json
from pathlib import Path
import sympy as S
x=S.Symbol('x',positive=True)
t=S.Symbol('t',real=True)
a=S.Symbol('a',real=True)
R=S.Rational
M=S.Matrix
def L(value):return S.latex(value).replace(r'\log',r'\ln')
ROOT=Path(__file__).resolve().parent.parent
CAT=json.loads((ROOT/'data/competency_matrix.json').read_text())
COMP={c['id']:c for c in CAT['competencies']}
QUESTIONS=[];SOLUTIONS={};CHECKS={}

def m(value):return r'\('+ (value if isinstance(value,str) else L(value)) +r'\)'
def tup(*v):return m(r'\left('+r'\mid '.join(map(str,v))+r'\right)')
def expr(value):return str(value)
def length_steps(components):
    dims=['x','y','z'][:len(components)]
    formula=r'\lVert\vec v\rVert=\sqrt{'+ '+'.join('v_'+d+'^2' for d in dims)+'}'
    squares='+'.join(r'\left('+L(S.sympify(c))+r'\right)^2' for c in components)
    total=sum(S.sympify(c)**2 for c in components)
    return ['Die allgemeine Längenformel lautet '+m(formula)+'.',
            'Die Komponenten beschreiben senkrechte Richtungen. Nach Pythagoras addierst du ihre Quadrate und ziehst anschließend die Wurzel; so erhältst du die Länge statt der Quadratsumme.',
            'Setze die Komponenten ein: '+m(r'\lVert\vec v\rVert=\sqrt{'+squares+r'}=\sqrt{'+L(total)+'}')+'.']

def point_distance_steps(start,end):
    dims=['x','y','z'][:len(start)]
    formula=r'd(A,B)=\lVert B-A\rVert=\sqrt{'+ '+'.join('('+d+'_B-'+d+'_A)^2' for d in dims)+'}'
    delta=M(end)-M(start)
    squares='+'.join(r'\left('+L(c)+r'\right)^2' for c in delta)
    return ['Der Punktabstand ist die Länge des Verbindungsvektors. Die allgemeine Formel ist '+m(formula)+'.',
            'Bilde zuerst die Koordinatendifferenzen, also Ziel minus Start: '+m(r'\overrightarrow{AB}=B-A='+L(delta))+'.',
            'Setze diese Differenzen in die Längenformel ein: '+m(r'd(A,B)=\sqrt{'+squares+'}')+'.']

def add(cid,slot,prompt,answer,wrong,steps,check=None,reason=''):
    c=COMP[cid];qid=f'{cid[0]}{100+(int(cid[1:])-1)*6+slot:03}'
    # Slot und ID sind dauerhaft; keine Zufallszahlen und kein abhängig vom Pool rotierender Schlüssel.
    values=[answer,*wrong];rotation=(int(cid[1:])+slot)%3
    options=values[rotation:]+values[:rotation];correct=options.index(answer)
    assert len(options)==len(set(options))==3,(qid,options)
    difficulty=(slot-1)//2+1
    q=dict(id=qid,domain=c['domain'],skill=c['skill'],subskill=c['skill']+'-1',mainTopic=c['mainTopic'],subtopic=c['subtopic'],competency=cid,competencies=[cid],difficulty=difficulty,deck=c['deck'],unlockEligible=difficulty==1,prerequisites=c['prerequisites'],variantFamily=f'{cid}-{difficulty}',prompt=prompt,options=options,validationStatus='automatically_validated' if check else 'manually_reviewed',domainNote=reason)
    QUESTIONS.append(q)
    SOLUTIONS[qid]=dict(correct=correct,explanation=' '.join(steps),steps=steps,background=c['outcome']+'. '+reason,misconception='Die beiden falschen Antworten stehen für vertauschte Rechenschritte, fehlende Bedingungen oder eine unpassende Regel.',oral='Erkläre, warum dein Verfahren passt und woran du einen Fehler erkennen würdest.')
    CHECKS[qid]=dict(status=q['validationStatus'],method=check or dict(kind='editorial',proof=steps),reviewScope='Symbolische/exakte Prüfung der gespeicherten Rechnung und Antwortalternativen; Textbezug redaktionell geprüft.' if check else 'Vom Aufgabenautor anhand der dokumentierten Begründung redaktionell geprüft; keine unabhängige Lehrkraftfreigabe.')
    return qid

def calc(cid,slot,prompt,source,wrongs,steps,operation='expression',reason=''):
    source=S.sympify(source)
    if operation=='derivative':result=S.diff(source,x)
    elif operation=='primitive':result=S.integrate(source,x)
    else:result=S.simplify(source)
    # Falsche Optionen müssen tatsächlich verschieden und im angegebenen Bereich falsch sein.
    result=S.simplify(result);wrongs=[S.simplify(w) for w in wrongs]
    assert len(wrongs)==2
    allv=[result,*wrongs]
    for i in range(3):
        for j in range(i):
            delta=allv[i]-allv[j]
            assert not (delta==0 or getattr(delta,'is_zero',None) is True), (cid,slot,allv)
            assert S.simplify(delta)!=S.zeros(*delta.shape) if isinstance(delta,S.MatrixBase) else S.simplify(delta)!=0,(cid,slot,allv)
    check=dict(kind=operation,source=expr(source),answers=[expr(z) for z in allv],variable='x',assumptions='x > 0' if source.has(x) else 'Exakte reelle Zahlen / Vektoren laut Aufgabenstellung')
    return add(cid,slot,prompt,m(result),[m(w) for w in wrongs],steps+[f'Damit erhältst du {m(result)}.'],check,reason)

def concept(cid,slot,prompt,answer,w1,w2,why,detail):
    return add(cid,slot,prompt,answer,[w1,w2],[why,detail])

def deriv(cid,slot,f,w1,w2,rule,intermediate):
    displayed=(r'f(x)=\frac{\sqrt{x}}{x^{'+str(slot-3)+r'}}') if cid=='A13' and slot>=5 else L(S.Eq(S.Function('f')(x),f))
    return calc(cid,slot,'Für '+m('x>0')+': Leite '+m(displayed)+' ab.',f,[w1,w2],[rule,intermediate],operation='derivative',reason='Die Einschränkung x > 0 vermeidet ausgeschlossene oder nicht differenzierbare Stellen; trigonometrische Argumente im Bogenmaß.')

def analysis():
 for k in [1,2]:
    n=k+2;v=k+1
    calc('A01',k,'Berechne '+m(R(1,n),)+ ' + '+m(R(1,2*n))+'.',R(1,n)+R(1,2*n),[R(2,3*n),R(1,2*n)],['Bringe beide Brüche auf den gemeinsamen Nenner '+str(2*n)+'.','Erweitere den ersten Zähler mit 2; die Zähler werden anschließend addiert.'])
    calc('A01',k+2,'Vereinfache für '+m('x>0')+' den Term '+m((x**2-n**2)/(x+n))+'.',(x**2-n**2)/(x+n),[x+n,x**2-n],['Zerlege die Differenz von Quadraten in '+m((x-n)*(x+n))+'.','Kürze nur den gemeinsamen Faktor '+m(x+n)+', nicht einzelne Summanden.'])
    concept('A01',k+4,'Beim Kürzen von '+m((x**2-v**2)/(x-v))+' behauptet jemand: Der ursprüngliche Term ist auch bei '+m(S.Eq(x,v))+' definiert. Was gilt?', 'Die gekürzte Form hat dort einen Wert, der ursprüngliche Bruch bleibt ausgeschlossen.','Durch das Kürzen wird die ausgeschlossene Stelle nachträglich erlaubt.','Der ganze ursprüngliche Definitionsbereich ist leer.','Der ursprüngliche Nenner wird bei dieser Stelle 0. Durch 0 darfst du nicht teilen.','Die Gleichheit mit der gekürzten Form gilt nur auf dem ursprünglichen Definitionsbereich.')
    calc('A02',k,'Vereinfache für '+m('x>0')+': '+m(r'x^{'+str(n)+r'}\cdot x^{-'+str(v)+r'}')+'.',x**n*x**(-v),[x**(n+v),x**(-n*v)],['Bei gleicher Basis addierst du beim Multiplizieren die Exponenten.','Der negative Exponent bedeutet einen Kehrwert; hier rechnest du '+str(n)+' − '+str(v)+'.'])
    calc('A02',k+2,'Vereinfache für '+m('x>0')+': '+m(r'(x^{-'+str(n)+r'})^2')+'.',x**(-2*n),[x**(-n+2),x**(2*n)],['Eine Potenz wird potenziert: Die Exponenten werden multipliziert.','Das Minus bleibt erhalten: '+str(-n)+' · 2 = '+str(-2*n)+'.'])
    calc('A02',k+4,'Vereinfache für '+m('x>0')+' und '+m(S.Symbol('y')>0)+': '+m(r'\frac{x^{-'+str(n)+r'}x^{'+str(n+1)+r'}}{'+str(v)+r'x^{-1}}')+'.',x**2/v,[x/v,x**2*v],['Fasse zuerst im Zähler die x-Potenzen zusammen.','Teilen durch x hoch −1 ist Multiplizieren mit x; der Zahlenfaktor bleibt im Nenner.'])
    calc('A03',k,'Berechne '+m(S.Pow(n*n,R(1,2),evaluate=False))+'.',S.sqrt(n*n),[-n,n*n],['Die Quadratwurzel ist per Definition nichtnegativ.','Gesucht ist die Zahl, deren Quadrat '+str(n*n)+' ergibt.'])
    calc('A03',k+2,'Vereinfache für '+m('x>0')+': '+m(r'\sqrt{x}\cdot x^{'+str(v)+r'}')+'.',x**(v+R(1,2)),[x**(v+2),x**(R(v,2))],['Schreibe die Wurzel als Potenz: '+m(S.Eq(S.sqrt(x),x**R(1,2),evaluate=False))+'.','Beim Multiplizieren gleicher Basen werden die Exponenten addiert.'])
    concept('A03',k+4,'Für reelles '+m(x)+' wird '+m(S.sqrt((x-v)**2))+' vereinfacht. Welche Aussage berücksichtigt auch '+m(x<v)+'?',m(r'\lvert x-'+str(v)+r'\rvert'),m(x-v),m(-(x-v)),'Die Quadratwurzel liefert nie einen negativen Wert.','Für x unterhalb von '+str(v)+' ist x − '+str(v)+' negativ und muss sein Vorzeichen wechseln; oberhalb bleibt es stehen.')
    calc('A04',k,'Berechne '+m(S.log(S.exp(n),evaluate=False))+'.',S.log(S.exp(n)),[S.exp(n),n+1],['Natürlicher Logarithmus und Exponentialfunktion sind Umkehrfunktionen.','Der Logarithmus fragt nach dem Exponenten zur Basis e.'])
    calc('A04',k+2,'Vereinfache für '+m('x>0')+': '+m(S.log(x**n,evaluate=False)-S.log(x,evaluate=False))+'.',S.expand_log(S.log(x**n)-S.log(x),force=True),[n*S.log(x),S.log(n*x)],['Für positive Argumente gilt ln(x hoch n) = n ln(x).','Ziehe anschließend einmal ln(x) ab; die Koeffizienten werden zusammengefasst.'])
    concept('A04',k+4,'Ist '+m(r'\ln(x+'+str(v)+r')=\ln(x)+\ln('+str(v)+r')')+' für alle '+m('x>0')+' richtig?', 'Nein, die Summenregel in dieser Form gibt es für den Logarithmus nicht.','Ja, Logarithmen lassen sich über Summen verteilen.','Ja, aber nur weil beide Argumente positiv sind.','Die Logarithmusregel betrifft Produkte: ln(ab) = ln(a) + ln(b).','Eine Summe im Argument darfst du nicht auf diese Weise zerlegen; Einsetzen eines positiven Werts liefert ein Gegenbeispiel.')
    calc('A05',k,'Löse '+m(r'3x-'+str(3*v)+r'='+str(3*n))+'. Gib '+m(x)+' an.',S.Integer(n+v),[n-v,3*(n+v)],['Addiere '+str(3*v)+' auf beiden Seiten.','Teile danach beide Seiten durch 3.'])
    concept('A05',k+2,'Welche reellen Lösungen hat '+m(r'x^2-'+str(n*n)+r'=0')+'?',m(r'x=\pm '+str(n)),m(S.Eq(x,n)),m(S.Eq(x,n*n)),'Bringe die Konstante auf die rechte Seite: x² = '+str(n*n)+'.','Sowohl '+str(n)+' als auch '+str(-n)+' ergeben beim Quadrieren die geforderte Zahl.')
    concept('A05',k+4,'Bei '+m(r'\sqrt{x+'+str(v)+r'}=-'+str(n))+' schlägt jemand Quadrieren als ersten Schritt vor. Wie viele reelle Lösungen sind möglich?', 'Keine: Eine Quadratwurzel kann nicht negativ sein.','Genau eine, die nach dem Quadrieren entsteht.','Genau zwei, weil Quadrieren immer zwei Lösungen erzeugt.','Die linke Seite ist für alle zulässigen x nichtnegativ, rechts steht eine negative Zahl.','Schon vor dem Rechnen ist klar, dass die Gleichung keine Lösung hat. Quadrieren könnte eine Scheinlösung erzeugen.')
    concept('A06',k,'Welcher Definitionsbereich gehört zu '+m(r'f(x)=\frac{1}{x-'+str(n)+r'}')+'?',m(r'\mathbb{R}\setminus\{'+str(n)+r'\}'),m(r'\mathbb{R}'),m(r'('+str(n)+r',\infty)'),'Ein Nenner darf nicht 0 werden.','Genau x = '+str(n)+' ist ausgeschlossen; negative Nenner sind sonst durchaus erlaubt.')
    concept('A06',k+2,'Welcher Definitionsbereich gehört zu '+m(r'f(x)=\ln(x-'+str(n)+r')')+'?',m(r'('+str(n)+r',\infty)'),m(r'['+str(n)+r',\infty)'),m(r'\mathbb{R}\setminus\{'+str(n)+r'\}'),'Das Argument des reellen Logarithmus muss strikt positiv sein.','Löse x − '+str(n)+' > 0. Der Randwert gehört nicht dazu, und alle kleineren Werte fallen ebenfalls weg.')
    concept('A06',k+4,'Welchen Wertebereich hat '+m(r'f(x)=('+str(n)+r'-x)^2+'+str(v))+' auf ganz '+m(r'\mathbb{R}')+'?',m(r'['+str(v)+r',\infty)'),m(r'['+str(n)+r',\infty)'),m(r'\mathbb{R}'),'Das Quadrat ist nie negativ und wird bei x = '+str(n)+' gleich 0.','Durch die Addition wird der kleinste Wert '+str(v)+'. Jeder größere Wert ist erreichbar.')
    calc('A07',k,'Für '+m(r'f(x)='+str(n)+r'x-'+str(v))+': Berechne '+m(r'f(2)')+'.',S.Integer(2*n-v),[2*n+v,n*2],['Setze 2 für jede Stelle x ein.','Multipliziere zuerst und ziehe anschließend die Konstante ab.'])
    concept('A07',k+2,'Welche Aussage über '+m(r'f(x)=x^{'+str(2*v)+r'}-'+str(n))+' ist richtig?', 'Der Graph ist zur y-Achse symmetrisch und nach unten beschränkt.','Der Graph ist zum Ursprung punktsymmetrisch.','Die Funktion ist auf ganz ℝ streng steigend.','Eine gerade Potenz ändert ihren Wert bei x und −x nicht.','Der Potenzteil ist nichtnegativ; der kleinste Funktionswert ist −'+str(n)+'.')
    concept('A07',k+4,'Für '+m(r'f(x)=x^3-'+str(n)+r'x')+' wird eine lineare Funktion als globales Modell vorgeschlagen. Warum passt das nicht?', 'Die Änderungsrate der kubischen Funktion hängt von x ab.','Eine Funktion mit einem x-Term ist immer linear.','Eine kubische Funktion besitzt gar keine Ableitung.','Die Ableitung lautet 3x² − '+str(n)+' und ist nicht konstant.','Eine Gerade hätte dagegen dieselbe Steigung an jeder Stelle; ein lineares Modell kann höchstens lokal angenähert passen.')
    calc('A08',k,'Berechne im Bogenmaß '+m(S.sin(S.pi/2,evaluate=False) if k==1 else S.cos(S.pi,evaluate=False))+'.',S.Integer(1 if k==1 else -1),[0,2 if k==1 else 1],['Orientiere dich am Einheitskreis.','Sinus ist die y-Koordinate, Kosinus die x-Koordinate des zugehörigen Kreispunkts.'])
    calc('A08',k+2,'Welche kleinste positive Periode hat '+m(r'f(x)=\sin('+str(n)+r'x)')+'?',2*S.pi/n,[2*S.pi*n,S.pi/n],['Sinus wiederholt seine Werte nach einer Änderung des Arguments um 2π.','Für n x muss deshalb n T = 2π gelten. Löse nach T auf.'])
    concept('A08',k+4,'Der Graph von '+m(r'f(x)='+str(v)+r'\cos('+str(n)+r'x)')+' wird untersucht. Welche Aussage stimmt?', 'Die Amplitude und die Frequenz ändern sich, die Mittellinie bleibt y = 0.','Die Amplitude ist '+str(n)+' und die Periodenlänge '+str(v)+'.','Der Faktor vor cos verschiebt den Graphen nach oben.','Der Faktor '+str(v)+' vor dem Kosinus skaliert die Höhe. Der Faktor '+str(n)+' im Argument verändert die Periodenlänge.','Kein addierter Wert außerhalb der Funktion bedeutet keine vertikale Verschiebung.')
    concept('A09',k,'Was bewirkt '+m(r'g(x)=f(x)+'+str(n))+'?',str(n)+' Einheiten nach oben.',str(n)+' Einheiten nach rechts.', 'Eine Streckung um den Faktor '+str(n)+'.','Die Zahl wird erst nach dem Funktionswert addiert.','Jeder y-Wert wird um '+str(n)+' größer; der x-Wert bleibt derselbe.')
    concept('A09',k+2,'Wie entsteht '+m(r'g(x)=-f(x-'+str(v)+r')')+' aus f?',str(v)+' nach rechts und Spiegelung an der x-Achse.',str(v)+' nach links und Spiegelung an der x-Achse.',str(v)+' nach rechts und Spiegelung an der y-Achse.','x − '+str(v)+' im Inneren verschiebt den Graphen nach rechts.','Das äußere Minus wechselt anschließend alle y-Vorzeichen und spiegelt an der x-Achse.')
    concept('A09',k+4,'Ein Punkt '+tup(n,v)+' liegt auf f. Welcher Punkt liegt sicher auf '+m(r'g(x)=2f(x-'+str(v)+r')+1')+'?',tup(n+v,2*v+1),tup(n-v,2*v+1),tup(2*n+1,v+v),'Um den alten Funktionswert bei x = '+str(n)+' zu erreichen, muss die neue Stelle '+str(n+v)+' sein.','Dann wird der alte y-Wert verdoppelt und 1 addiert. Die Reihenfolge folgt der Funktionsvorschrift.')
    concept('A10',k,'Welche Nullstellen hat '+m(r'f(x)=x(x-'+str(n)+r')')+'?',m(r'x=0\text{ oder }x='+str(n)),m(S.Eq(x,n)),m(S.Eq(x,-n,evaluate=False)),'Ein Produkt ist genau dann 0, wenn mindestens ein Faktor 0 ist.','Prüfe also x = 0 und x − '+str(n)+' = 0 getrennt. Nicht vorher durch x teilen, sonst verlierst du eine Lösung.')
    concept('A10',k+2,'Welche waagerechte Asymptote hat '+m(r'f(x)=\frac{'+str(n)+r'x+1}{x+2}')+'?',m(r'y='+str(n)),m(r'y=0'),m(r'y=1'),'Für sehr große Beträge von x bestimmen die höchsten Potenzen den Grenzwert.','Zähler und Nenner haben denselben Grad. Der Quotient der führenden Koeffizienten ist '+str(n)+'.')
    concept('A10',k+4,'An '+m(r'f(x)=(x-'+str(v)+r')^2(x+'+str(n)+r')')+' wird die Nullstelle '+m(S.Eq(x,v))+' betrachtet. Was passiert am Graphen?', 'Der Graph berührt dort die x-Achse ohne Vorzeichenwechsel.','Der Graph muss dort sein Vorzeichen wechseln.','An einer doppelten Nullstelle ist die Funktion nicht definiert.','Der Faktor (x − '+str(v)+')² hat eine gerade Vielfachheit und bleibt beidseits nichtnegativ.','Der andere Faktor ist an der Stelle positiv und ungleich 0. Deshalb bleibt das Vorzeichen in ihrer Umgebung gleich.')
    calc('A11',k,'Für '+m(r'f(x)=x^2')+': Bestimme die mittlere Änderungsrate von '+m(n)+' bis '+m(n+v)+'.',S.Rational((n+v)**2-n**2,v),[v,2*n],['Bilde die Differenz der Funktionswerte und teile durch die Differenz der x-Werte.','Der Nenner ist '+str(v)+', nicht der größere x-Wert.'])
    calc('A11',k+2,'Die Position ist '+m(r's(t)='+str(v)+r't^2')+'. Wie groß ist die momentane Geschwindigkeit bei '+m(r't='+str(n))+'?',2*v*n,[v*n*n,v*n],['Die momentane Geschwindigkeit ist die Ableitung der Position.','Es gilt s′(t) = '+str(2*v)+'t. Setze erst danach den Zeitpunkt ein.'])
    concept('A11',k+4,'Beim Differenzenquotienten von '+m(r'f(x)=x^2')+' an '+m(S.Eq(x,n))+' wird nach Kürzen '+m(r'2\cdot '+str(n)+r'+h')+' erhalten. Wie entsteht daraus die Ableitung?', 'Lass h gegen 0 gehen; der Grenzwert ist '+str(2*n)+'.','Setze im ursprünglichen Bruch sofort h = 0.','Der Grenzwert ist '+str(n*n)+', weil f(x) = x².','Der ursprüngliche Quotient ist bei h = 0 nicht definiert, der Grenzwert kann aber existieren.','Nach dem Kürzen für h ≠ 0 kannst du den Grenzwert ablesen; das unterscheidet Differential- und Differenzenquotient.')
    deriv('A12',k,n*x**v,n*x**(v-1),n*v*x**v,'Nutze Potenzregel und Faktorregel.','Der Exponent kommt nach vorn und wird danach um 1 kleiner.')
    deriv('A12',k+2,n*x**3-v*x+7,3*n*x**2-v+7,n*x**2-v,'Leite die Summanden einzeln ab.','Die Konstante 7 hat Ableitung 0; feste Faktoren bleiben stehen.')
    deriv('A12',k+4,(x-v)**2,(x-v),2*x,'Du kannst zuerst die Klammer ausmultiplizieren.','Die Ableitung von x² − '+str(2*v)+'x + '+str(v*v)+' ist 2x − '+str(2*v)+'.')
    deriv('A13',k,S.sqrt(x),S.sqrt(x)/2,1/S.sqrt(x),'Schreibe die Wurzel als x hoch 1/2.','Die Potenzregel liefert (1/2)x hoch −1/2; die Ableitung gilt nur für x > 0.' ) if k==1 else deriv('A13',k,x**R(1,3),x**R(-2,3),R(1,3)*x**R(2,3),'Schreibe die dritte Wurzel als Potenz.','Beim Ableiten wird aus dem Exponenten 1/3 der Exponent −2/3.')
    deriv('A13',k+2,x**(-n),n*x**(-n-1),-n*x**(-n+1),'Wende die Potenzregel auch beim negativen Exponenten an.','Das Minuszeichen des Exponenten wird Teil des Vorfaktors.')
    deriv('A13',k+4,S.sqrt(x)/x**v,(-v+R(1,2))*x**(-v+R(1,2)),(v+R(1,2))*x**(-v-R(1,2)),'Vereinfache vor dem Ableiten: gleiche Basis, Exponenten subtrahieren.','Der Ausdruck ist x hoch (1/2 − '+str(v)+'). Darauf passt direkt die Potenzregel.')
    deriv('A14',k,x*S.exp(n*x),S.exp(n*x),n*S.exp(n*x),'Nutze die Produktregel u′v + uv′.','Für u = x gilt u′ = 1, für v = exp('+str(n)+'x) gilt v′ = '+str(n)+'exp('+str(n)+'x).')
    deriv('A14',k+2,(x+v)*(x**2+n),2*x, (x**2+n)+x*(x+v),'Auch eine verschobene lineare Funktion ist ein eigener Faktor.','Leite jeden Faktor in genau einem Summanden ab; addiere beide Produkte.')
    deriv('A14',k+4,x**2*S.log(x+v),2*x/(x+v),2*x*S.log(x+v)+x**2/(x+v)**2,'Du brauchst Produktregel und die Ableitung des Logarithmus.','Die Ableitungen der Faktoren sind 2x und 1/(x + '+str(v)+').')
    deriv('A15',k,x/(x+n),n/(x+n),1/(x+n)**2,'Nutze die Quotientenregel (u′v − uv′)/v².','Im Zähler bleibt (x + '+str(n)+') − x = '+str(n)+'.')
    deriv('A15',k+2,(x**2+v)/(x+n),(2*x*(x+n)+(x**2+v))/(x+n)**2,2*x/(x+n),'Der Nenner ist für x > 0 nicht 0.','Im Zähler steht 2x(x + '+str(n)+') − (x² + '+str(v)+'), darunter das Quadrat des Nenners.')
    deriv('A15',k+4,S.log(x)/(x+v),(1/x)/(x+v),((x+v)/x+S.log(x))/(x+v)**2,'Verknüpfe Quotientenregel und (ln x)′ = 1/x.','Achte auf das Minus vor ln(x) im Zähler und auf das Nennerquadrat.')
    deriv('A16',k,(n*x+1)**3,3*(n*x+1)**2,3*n*(n*x+1)**3,'Nutze äußere Ableitung mal innere Ableitung.','Die äußere dritte Potenz liefert 3(innerer Term)²; innen ist die Ableitung '+str(n)+'.')
    deriv('A16',k+2,S.sqrt(n*x**2+1),1/(2*S.sqrt(n*x**2+1)),2*n*x/S.sqrt(n*x**2+1),'Die äußere Funktion ist eine Wurzel.','Nach der äußeren Ableitung musst du mit der inneren Ableitung '+str(2*n)+'x multiplizieren.')
    deriv('A16',k+4,S.sin((x**2+v)**3),S.cos((x**2+v)**3),3*(x**2+v)**2*S.cos((x**2+v)**3),'Es liegen drei Schichten vor: Sinus, dritte Potenz, quadratischer Term.','Multipliziere cos(inneres Argument), 3(x² + '+str(v)+')² und 2x.')
    deriv('A17',k,S.exp(n*x),S.exp(n*x),x*S.exp(n*x),'Die e-Funktion bleibt beim Ableiten erhalten.','Der lineare Exponent bringt über die Kettenregel den zusätzlichen Faktor '+str(n)+'.')
    deriv('A17',k+2,v*S.exp(-n*x),v*S.exp(-n*x),v*n*S.exp(-n*x),'Nutze Faktorregel und Kettenregel.','Die innere Ableitung des negativen Exponenten ist −'+str(n)+', daher wird die Ableitung negativ.')
    deriv('A17',k+4,S.exp(x**2+v),S.exp(x**2+v),2*S.exp(x**2+v),'Leite auch den nichtlinearen Exponenten ab.','Die e-Funktion wird mit 2x multipliziert; eine additive Konstante im Exponenten hat Ableitung 0.')
    deriv('A18',k,S.log(x+v),1/x,1/(x+v)**2,'Die Ableitung von ln(u) ist u′/u.','Innen steht x + '+str(v)+' mit Ableitung 1.')
    deriv('A18',k+2,S.log(n*x**2+1),1/(n*x**2+1),n*x/(n*x**2+1),'Nutze die Kettenregel beim natürlichen Logarithmus.','Teile die innere Ableitung '+str(2*n)+'x durch das ursprüngliche positive Argument.')
    deriv('A18',k+4,S.log(x)/(x**v),1/x**(v+1),v*S.log(x)/x**(v+1),'Schreibe den Term als x hoch −'+str(v)+' mal ln(x).','Die Produktregel ergibt einen Summanden mit ln(x) und einen mit der Ableitung 1/x.')
    deriv('A19',k,S.sin(n*x),S.cos(n*x),-n*S.sin(n*x),'Nutze (sin u)′ = cos(u) · u′ im Bogenmaß.','Die innere lineare Funktion hat die Ableitung '+str(n)+'.')
    deriv('A19',k+2,S.cos(n*x+v),n*S.sin(n*x+v),-S.sin(n*x+v),'Kosinus wird beim Ableiten zu negativem Sinus.','Die Kettenregel ergänzt den Faktor '+str(n)+'.')
    deriv('A19',k+4,S.sin(x)**v,v*S.sin(x)**(v-1),v*S.cos(x)**(v-1),'Die äußere Funktion ist eine Potenz, innen steht sin(x).','Leite die Potenz ab und multipliziere mit cos(x).')
    deriv('A20',k,x*S.sin(n*x),S.sin(n*x),n*x*S.cos(n*x),'Zunächst Produktregel, im zweiten Faktor zusätzlich Kettenregel.','Ein Summand entsteht aus der Ableitung von x, einer aus der Ableitung des Sinus.')
    deriv('A20',k+2,(x+v)*S.exp(x**2),S.exp(x**2),S.exp(x**2)+2*x*S.exp(x**2),'Die beiden Faktoren sind x + '+str(v)+' und exp(x²).','Beim zweiten Faktor liefert die Kettenregel 2x exp(x²).')
    deriv('A20',k+4,S.log(x+v)/S.sqrt(x),1/((x+v)*S.sqrt(x)),S.log(x+v)/(2*x**R(3,2)),'Nutze Produktregel mit x hoch −1/2 und die Logarithmusableitung.','Die Ableitung des Wurzel-Kehrwerts ist negativ; der andere Summand enthält 1/(x + '+str(v)+').')
    calc('A21',k,'Für '+m(r'f(x)=x^2')+': Welche Steigung hat die Tangente bei '+m(S.Eq(x,n))+'?',2*n,[n*n,n],['Die Tangentensteigung ist der Wert der ersten Ableitung an der Stelle.','Bei f′(x) = 2x setzt du '+str(n)+' ein.'])
    calc('A21',k+2,'Für '+m(r'f(x)=x^2')+': Gib die Normalensteigung bei '+m(S.Eq(x,v))+' an.',-R(1,2*v),[2*v,R(1,2*v)],['Die Tangentensteigung ist '+str(2*v)+'. Sie ist nicht 0.','Bei senkrechten Geraden ist das Produkt der Steigungen −1. Nimm deshalb den negativen Kehrwert.'])
    concept('A21',k+4,'Für '+m(r'f(x)=(x-'+str(n)+r')^2+'+str(v))+' wird die Normale im Scheitel gesucht. Was gilt?',m(r'x='+str(n)),m(r'y='+str(v)),m(r'y=-x+'+str(n+v)),'Die Tangente im Scheitel ist waagerecht. Ihre Normale ist daher senkrecht.','Eine senkrechte Gerade kann nicht als y = mx + b mit endlicher Steigung dargestellt werden; sie hat die Gleichung x = '+str(n)+'.')
    concept('A22',k,'Auf einem Intervall gilt '+m(r'f\prime(x)<-'+str(v))+'. Was folgt?', 'f ist dort streng fallend.','f hat dort ausschließlich negative Funktionswerte.','f ist dort konstant.','Eine überall negative Ableitung bedeutet fallende Funktionswerte, wenn x größer wird.','Das Vorzeichen der Ableitung legt nicht das Vorzeichen der Funktion selbst fest.')
    concept('A22',k+2,'Für '+m(r'f(x)=(x-'+str(n)+r')^2')+': Auf welchem Intervall ist f streng steigend?',m(r'('+str(n)+r',\infty)'),m(r'(-\infty,'+str(n)+r')'),m(r'\mathbb{R}'),'Es gilt f′(x) = 2(x − '+str(n)+').','Die Ableitung ist genau rechts von '+str(n)+' positiv. Links davon ist sie negativ.')
    concept('A22',k+4,'Eine Funktion hat die Ableitung '+m(r'f\prime(x)=(x-'+str(n)+r')^2')+'. Was ist trotz der Nullstelle der Ableitung möglich?', 'Die Funktion ist auf ganz ℝ streng steigend.','Jede Nullstelle von f′ erzeugt einen Hochpunkt.','Die Funktion muss links der Stelle fallen.','Die Ableitung ist überall nichtnegativ und nur an einer einzelnen Stelle 0.','Zum Beispiel hat (x − '+str(n)+')³/3 genau diese Ableitung und steigt trotz waagerechter Tangente streng an.')
    concept('A23',k,'Es gilt '+m(r'f\prime('+str(n)+r')=0')+' und '+m(r'f\prime\prime('+str(n)+r')='+str(v))+'. Was ist nachgewiesen?', 'Ein lokaler Tiefpunkt an dieser Stelle.','Ein lokaler Hochpunkt an dieser Stelle.','Allein daraus folgt ein Wendepunkt.','Die erste Ableitung 0 bedeutet eine waagerechte Tangente.','Die positive zweite Ableitung macht daraus einen Tiefpunkt; ohne die zweite Bedingung wäre das noch nicht sicher.')
    calc('A23',k+2,'An welcher Stelle nimmt '+m(r'f(x)=x^2-'+str(2*n)+r'x+'+str(v))+' sein Minimum an?',n,[-n,2*n],['Setze die Ableitung 2x − '+str(2*n)+' gleich 0.','Die zweite Ableitung ist 2 > 0; die nach oben geöffnete Parabel hat dort ihr Minimum.'])
    concept('A23',k+4,'Für '+m(r'f(x)=x^3')+' auf dem abgeschlossenen Intervall '+m(r'[-'+str(n)+r';'+str(v)+r']')+' wird nur '+m(r'f\prime(0)=0')+' geprüft. Welche Ergänzung ist nötig?', 'Auch die Randwerte vergleichen; x = 0 ist hier kein Extremum.','x = 0 ist automatisch das globale Maximum.','Randpunkte dürfen nie globale Extrema sein.','x³ steigt auf dem ganzen Intervall. Eine stationäre Stelle allein ist kein Extremnachweis.','Das kleinste und das größte Ergebnis auf dem abgeschlossenen Intervall liegen hier an den beiden Rändern.')
    concept('A24',k,'Es gilt auf einem Intervall '+m(r'f\prime\prime(x)='+str(n))+'. Welche Krümmung liegt vor?', 'Nach oben gekrümmt (konvex).','Nach unten gekrümmt (konkav).','Daraus folgt eine Gerade.','Die zweite Ableitung ist positiv. Die Steigung der Funktion nimmt daher zu.','Eine positive konstante zweite Ableitung passt zum Beispiel zu einer nach oben geöffneten Parabel.')
    calc('A24',k+2,'An welcher Stelle hat '+m(r'f(x)=(x-'+str(n)+r')^3')+' einen Wendepunkt?',n,[-n,0],['Die zweite Ableitung ist 6(x − '+str(n)+'). Sie ist bei '+str(n)+' gleich 0.','Links und rechts wechselt sie das Vorzeichen; damit ist der Krümmungswechsel nachgewiesen.'])
    concept('A24',k+4,'Für '+m(r'f(x)=(x-'+str(n)+r')^4')+' gilt am Punkt '+m(S.Eq(x,n))+' die Bedingung f″ = 0. Warum liegt dort trotzdem kein Wendepunkt?', 'Die zweite Ableitung wechselt dort nicht das Vorzeichen.','Eine vierte Potenz hat keine zweite Ableitung.','f″ = 0 beweist immer einen Wendepunkt.','Die zweite Ableitung ist 12(x − '+str(n)+')² und daher auf beiden Seiten nichtnegativ.','Eine Nullstelle von f″ ist nur ein Kandidat. Der notwendige Krümmungswechsel fehlt hier.')
    concept('A25',k,'Für '+m(r'f_a(x)=x^2+a')+' wird '+m(r'a='+str(n))+' eingesetzt. Welche Eigenschaft verändert sich gegenüber a = 0?', 'Die Höhe des Scheitels, nicht die Krümmungsrichtung.','Die Steigung f′(x) an jeder Stelle.','Die Breite der Parabel.','Ein addierter Parameter verschiebt den Graphen nur vertikal.','Die Ableitungen 2x und 2 bleiben gleich; die Scheitelhöhe ist jetzt '+str(n)+'.')
    concept('A25',k+2,'Links von '+m(S.Eq(x,n))+' gilt f(x) = x, rechts und an der Stelle gilt '+m(r'f(x)=x+'+str(v))+'. Was liegt an der Übergangsstelle vor?', 'Eine Sprungstelle; die beiden einseitigen Grenzwerte sind verschieden.','Stetigkeit, weil beide Teilfunktionen linear sind.','Ein glatter Übergang, weil beide Steigungen 1 sind.','Links nähert sich der Funktionswert '+str(n)+', rechts ist der Grenzwert '+str(n+v)+'.','Gleiche Steigungen genügen nicht für Stetigkeit. Ohne Stetigkeit kann der Übergang auch nicht differenzierbar sein.')
    concept('A25',k+4,'Bei '+m(r'f_a(x)=x^3-a x')+' mit '+m(r'a='+str(n))+'> 0 wird nach der Zahl der Extremstellen gefragt. Welche Begründung stimmt?', 'Zwei Extremstellen: f′ hat zwei einfache reelle Nullstellen.','Keine Extremstelle, weil ein Polynom dritten Grades immer steigt.','Genau eine Extremstelle, weil f′ quadratisch ist.','Aus 3x² − a = 0 folgt x = ±√(a/3), also zwei verschiedene Stellen.','Die zweite Ableitung 6x ist an beiden Stellen nicht 0 und bestätigt einen Hoch- und einen Tiefpunkt.')
    calc('A26',k,'Welche Funktion ist eine Stammfunktion von '+m(n*x**v)+'? Wähle die Variante ohne additive Konstante.',n*x**v,[n*x**(v-1),n*x**(v+1)],['Beim Integrieren einer Potenz steigt der Exponent um 1.','Teile den bisherigen Koeffizienten durch den neuen Exponenten. Durch Ableiten kannst du das Ergebnis prüfen.'],operation='primitive')
    calc('A26',k+2,'Welche Funktion ist eine Stammfunktion von '+m(S.exp(n*x))+'?',S.exp(n*x),[S.exp(n*x),n*S.exp(n*x)],['Beim Ableiten von exp(nx) entsteht der Faktor n.','Die Stammfunktion muss diesen Faktor durch Teilen durch n ausgleichen.'],operation='primitive')
    concept('A26',k+4,'Für '+m(r'f(x)=1/x')+' auf '+m('x>0')+' wird '+m(r'F(x)=\ln(x)+'+str(n))+' vorgeschlagen. Welche Aussage ist korrekt?', 'F ist eine Stammfunktion, und jede andere unterscheidet sich nur durch eine Konstante.','Die Potenzregel liefert x⁰/0 als Stammfunktion.','Nur die Konstante 0 ist erlaubt.','Bei x hoch −1 greift die übliche Potenzregel für Stammfunktionen nicht, weil der neue Exponent 0 wäre.','Stattdessen ist ln(x) eine Stammfunktion. Eine feste additive Zahl verschwindet beim Ableiten.')
    calc('A27',k,'Berechne '+m(r'\int_0^'+str(n)+r' 2x\,dx')+'.',S.integrate(2*x,(x,0,n)),[2*n,n],['Eine Stammfunktion von 2x ist x².','Setze die obere Grenze ein und ziehe den Wert an der unteren Grenze ab.'])
    concept('A27',k+2,'Für stetiges f gilt '+m(r'F(x)=\int_'+str(v)+r'^x f(t)\,dt')+'. Welche Ableitung hat F?',m(r'F\prime(x)=f(x)'),m(r'F\prime(x)=f(x)-f('+str(v)+r')'),m(r'F\prime(x)=0'),'Nach dem Hauptsatz der Differential- und Integralrechnung hebt Ableiten die Integration mit variabler oberer Grenze auf.','Die feste untere Grenze beeinflusst die Konstante der Integralfunktion, nicht ihre Ableitung.')
    calc('A27',k+4,'Der Graph '+m(r'f(x)='+str(v))+ ' rotiert auf '+m(r'[0;'+str(n)+r']')+' um die x-Achse. Wie groß ist das Rotationsvolumen?',S.pi*v*v*n,[S.pi*v*n,S.pi*v*v],['Jeder Querschnitt ist ein Kreis mit Radius '+str(v)+'. Seine Fläche ist π mal Radius zum Quadrat.','Integriere diese konstante Kreisfläche über die Länge '+str(n)+'.'])
    concept('A28',k,'Eine Funktion hat auf '+m(r'[0;'+str(n)+r']')+' den konstanten Wert −2. Was ist der Integralwert?',str(-2*n),str(2*n),str(-n),'Das bestimmte Integral zählt Flächen unterhalb der x-Achse negativ.','Rechne Höhe mal Breite: −2 · '+str(n)+' = '+str(-2*n)+'. Der geometrische Flächeninhalt wäre dagegen positiv.')
    calc('A28',k+2,'Berechne den geometrischen Flächeninhalt zwischen '+m(r'f(x)=x')+' und der x-Achse auf '+m(r'[-'+str(n)+r';'+str(n)+r']')+'.',S.Integer(n*n),[0,2*n*n],['Links der 0 liegt der Graph unter der x-Achse. Für eine geometrische Fläche zählst du beide Teile positiv.','Jedes der zwei Dreiecke hat Grundseite und Höhe '+str(n)+'. Addiere zweimal die halbe Grundseite mal Höhe.'])
    concept('A28',k+4,'Eine Funktion ist stetig und ihr Integral auf '+m(r'[-'+str(n)+r';'+str(n)+r']')+' ist 0. Was folgt sicher?', 'Positive und negative Beiträge heben sich auf; die geometrische Fläche kann trotzdem positiv sein.','Der Graph liegt überall auf der x-Achse.','Jeder einzelne Funktionswert ist 0.','Ein Integral ist eine vorzeichenbehaftete Gesamtbilanz.','Zum Beispiel hat f(x) = x auf diesem symmetrischen Intervall Integral 0, aber zwei nicht verschwindende Flächenteile.')
    calc('A29',k,'Berechne die Fläche zwischen '+m(r'f(x)='+str(n))+ ' und '+m(r'g(x)=x')+' auf '+m(r'[0;'+str(n)+r']')+'.',S.integrate(n-x,(x,0,n)),[n*n,n],['Auf dem ganzen Intervall liegt f über g.','Integriere daher f − g = '+str(n)+' − x zwischen den angegebenen Grenzen.'])
    calc('A29',k+2,'Welche Fläche liegt zwischen '+m(r'f(x)=x')+' und '+m(r'g(x)=x^2/'+str(n))+' von 0 bis zu ihrem positiven Schnittpunkt?',S.integrate(x-x**2/n,(x,0,n)),[S.Rational(n*n,3),S.Rational(n*n,2)],['Die Schnittgleichung x = x²/'+str(n)+' liefert 0 und '+str(n)+'.','Dazwischen ist x größer als x²/'+str(n)+'. Integriere obere minus untere Funktion.'])
    concept('A29',k+4,'Zwei stetige Graphen schneiden sich im Inneren von '+m(r'[-'+str(n)+r';'+str(n)+r']')+'. Warum genügt das Integral von f − g nicht immer als Flächeninhalt?', 'Beim Wechsel des oberen Graphen muss man aufteilen oder den Betrag der Differenz integrieren.','Jeder Schnittpunkt macht die geometrische Fläche 0.','Man muss stattdessen f + g integrieren.','f − g kann an einem Schnittpunkt das Vorzeichen wechseln. Dann heben sich Teilflächen im Integral auf.','Für einen geometrischen Flächeninhalt darf kein Teil negativ gezählt werden.')
    calc('A30',k,'Ein Behälter verliert konstant '+str(n)+' Liter pro Minute. Welche Bestandsänderung ergibt sich in '+str(v)+' Minuten?',-n*v,[n*v,-n-v],['Eine Verlust-Rate erhält ein negatives Vorzeichen.','Multipliziere Rate und Zeit. Liter pro Minute mal Minuten ergibt Liter.'])
    calc('A30',k+2,'Der Anfangsbestand ist 10 Liter und der Zufluss '+m(r'r(t)='+str(v)+r't')+' Liter/Minute. Wie groß ist der Bestand nach '+str(n)+' Minuten?',10+R(v*n*n,2),[R(v*n*n,2),10+v*n],['Der Bestand ist Anfangsbestand plus Integral der Rate von 0 bis '+str(n)+'.','Eine Stammfunktion von '+str(v)+'t ist '+str(v)+'/2 · t². Vergiss die anfänglichen 10 Liter nicht.'])
    concept('A30',k+4,'Eine Rate ist auf '+m(r'[0;'+str(n)+r']')+' positiv, nimmt aber ab. Was bedeutet das für den Bestand?', 'Der Bestand steigt weiter, aber immer langsamer.','Der Bestand muss schon abnehmen.','Der Bestand bleibt konstant, sobald die Rate abnimmt.','Positive Rate bedeutet positive Bestandsänderung, also weiter steigenden Bestand.','Erst eine negative Rate würde den Bestand sinken lassen; die Abnahme der Rate beschreibt hier nur die sinkende Steigung.')
    calc('A31',k,'Ein Bestand wächst pro Schritt um '+str(5*v)+' %. Welcher Faktor gehört dazu?',1+R(5*v,100),[R(5*v,100),1-R(5*v,100)],['Der alte Bestand entspricht 100 %.','Addiere den Zuwachs und schreibe die Prozentzahl als Dezimalzahl oder Bruch.'])
    calc('A31',k+2,'Ein Bestand wird durch '+m(r'B(t)=100e^{-'+str(v)+r't}')+' beschrieben. Welche Halbwertszeit hat das Modell?',S.log(2)/v,[v*S.log(2),-S.log(2)/v],['Die Hälfte des Anfangsbestands bedeutet exp(−'+str(v)+'t) = 1/2.','Logarithmiere und teile durch −'+str(v)+'. Die Halbwertszeit muss positiv sein.'])
    concept('A31',k+4,'Für '+m(r'B(t)='+str(10*n)+r'e^{0{,}2t}')+' behauptet jemand, pro Zeiteinheit kämen immer '+str(2*n)+' Einheiten hinzu. Was gilt?', 'Der relative Zuwachs ist konstant; der absolute Zuwachs hängt vom aktuellen Bestand ab.','Der absolute Zuwachs ist bei jedem exponentiellen Modell konstant.','Die Funktion beschreibt wegen des Faktors 0,2 eine Abnahme.','Die Ableitung ist 0,2 · B(t), also proportional zum aktuellen Bestand.','Eine feste absolute Zunahme würde zu einem linearen Modell führen. Die Rate zu Beginn darf nicht auf alle Zeiten übertragen werden.')
    calc('A32',k,'Ein Rechteck mit Umfang '+str(4*n)+' hat Seiten x und y. Wie groß ist die zweite Seite y als Ausdruck in x?',2*n-x,[4*n-x,n-x],['Der Umfang ist 2x + 2y. Setze die vorgegebene Zahl ein.','Teile durch 2 und löse danach nach y auf.'])
    calc('A32',k+2,'Ein Rechteck hat Umfang '+str(4*n)+'. Bei welcher Seitenlänge x ist die Fläche maximal?',n,[2*n,R(n,2)],['Mit y = '+str(2*n)+' − x lautet die Fläche x('+str(2*n)+' − x).','Die Ableitung '+str(2*n)+' − 2x wird bei x = '+str(n)+' null; die zweite Ableitung ist negativ.'])
    concept('A32',k+4,'Bei einer Optimierung auf '+m(r'[0;'+str(n)+r']')+' wird eine Stelle mit f′ = 0 gefunden. Reicht das für ein globales Maximum?', 'Nein. Art der Stelle und zulässige Randwerte müssen ebenfalls geprüft werden.','Ja, jede waagerechte Tangente ist ein globales Maximum.','Ja, sobald der Funktionswert positiv ist.','Eine Ableitungsnullstelle ist zunächst nur ein Kandidat und könnte ein Minimum oder eine Sattelstelle sein.','Selbst ein lokales Maximum kann niedriger sein als ein Randwert. Vergleiche alle zulässigen Kandidaten.')
    calc('A33',k,'Ein Eintritt kostet '+str(n)+' € Grundpreis und '+str(v)+' € pro Fahrt. Welche Kosten entstehen bei 4 Fahrten?',n+4*v,[4*(n+v),4*v],['Der Grundpreis fällt genau einmal an.','Addiere den Preis von vier Fahrten dazu; multipliziere den Grundpreis nicht mit der Fahrtenzahl.'])
    concept('A33',k+2,'Ein Modell zählt Personen und liefert für einen zulässigen Tag den Wert −'+str(n)+'. Was ist der passende nächste Schritt?', 'Annahmen, Definitionsbereich und Eignung des Modells prüfen.','Die negative Anzahl als reale Personenzahl ausgeben.','Ohne Prüfung nur das Vorzeichen ändern.','Negative Personenzahlen sind in diesem Sachkontext nicht sinnvoll.','Eine rechnerisch mögliche Ausgabe ist nicht automatisch eine sinnvolle reale Aussage; das Modell oder seine Anwendung kann ungeeignet sein.')
    concept('A33',k+4,'Ein lineares Modell wurde aus Messungen für '+m(r'0\le t\le '+str(n))+' entwickelt. Was lässt sich über die Vorhersage bei '+m(r't='+str(100*n))+' sagen?', 'Das ist eine Extrapolation; die Gültigkeit außerhalb der Messspanne muss geprüft werden.','Die Vorhersage ist allein wegen der Formel sicher gültig.','Jede Extrapolation ist mathematisch nicht ausrechenbar.','Die Formel kann zwar einen Wert liefern, sie wurde aber nur im angegebenen Bereich mit Daten verglichen.','Außerhalb davon können andere Prozesse oder Modellgrenzen auftreten. Rechenbarkeit ist kein Gültigkeitsbeweis.')

def geometry():
 for k in [1,2]:
    n=k+2;v=k+1
    calc('G01',k,'Welche y-Koordinate hat '+m(r'P('+str(n)+r'\mid -'+str(v)+r'\mid 1)')+'?',-v,[v,n],['Die Koordinaten stehen in der Reihenfolge x, y, z.','Gesucht ist die zweite Zahl einschließlich ihres Vorzeichens.'])
    calc('G01',k+2,'Spiegle '+m(r'P('+str(n)+r'\mid -'+str(v)+r'\mid 1)')+' an der xz-Ebene. Welches Koordinatentupel entsteht?',M([n,v,1]),[M([-n,-v,1]),M([n,-v,-1])],['Die xz-Ebene hat y = 0.','Beim Spiegeln wechselt nur die y-Koordinate das Vorzeichen. Die anderen beiden bleiben gleich.'])
    calc('G01',k+4,'Spiegle '+m(r'P('+str(n)+r'\mid '+str(v)+r'\mid 1)')+' zuerst an der yz-Ebene und verschiebe danach um '+m(M([1,0,2]))+'. Welches Tupel entsteht?',M([1-n,v,3]),[M([-(n+1),v,3]),M([1-n,-v,3])],['Die Spiegelung an x = 0 wechselt nur das Vorzeichen der x-Koordinate.','Addiere danach den Verschiebungsvektor. Die Reihenfolge der Operationen ist wichtig.'])
    calc('G02',k,'Von '+m(r'A(1\mid 2\mid 0)')+' nach '+m(r'B('+str(n)+r'\mid '+str(v)+r'\mid 3)')+': Welcher Verbindungsvektor führt von A nach B?',M([n-1,v-2,3]),[M([1-n,2-v,-3]),M([n+1,v+2,3])],['Ein Verbindungsvektor ist Zielpunkt minus Startpunkt.','Subtrahiere die drei Koordinaten jeweils an derselben Stelle.'])
    calc('G02',k+2,'Bestimme den Mittelpunkt von '+m(r'A(0\mid -2\mid 4)')+' und '+m(r'B('+str(2*n)+r'\mid '+str(2*v)+r'\mid 0)')+'. Welches Tupel passt?',M([n,v-1,2]),[M([2*n,2*v-2,4]),M([n,v+1,2])],['Der Mittelpunkt liegt in jeder Koordinatenrichtung auf halbem Weg.','Addiere die entsprechenden Koordinaten und teile jede Summe durch 2.'])
    concept('G02',k+4,'Eine Person berechnet für '+m(r'A('+str(n)+r'\mid 1)')+' und '+m(r'B('+str(v)+r'\mid 4)')+' den Vektor A − B als Weg von A nach B. Welcher Fehler liegt vor?', 'A − B zeigt von B nach A; benötigt wird B − A.','Die Koordinaten darf man nie subtrahieren.','Der Startpunkt eines Verbindungsvektors ist immer der Ursprung.','Der Vektor beschreibt die Änderung vom Start zum Ziel. Deshalb gilt Ziel minus Start.','A − B ist zwar ein gültiger Vektor, hat aber genau die entgegengesetzte Richtung.')
    calc('G03',k,'Berechne '+m(M([n,1,-2]))+' + '+m(M([1,-v,3]))+'.',M([n+1,1-v,1]),[M([n-1,1+v,-5]),M([n,v,1])],['Addiere erste zu erster, zweite zu zweiter und dritte zu dritter Komponente.','Negative Komponenten werden mit ihrem Vorzeichen addiert.'])
    calc('G03',k+2,'Berechne '+m(r'2'+L(M([n,1,-2]))+r'-'+L(M([1,v,3])))+'.',M([2*n-1,2-v,-7]),[M([2*n-2,2-2*v,-10]),M([2*n+1,2+v,-1])],['Multipliziere zuerst jede Komponente des ersten Vektors mit 2.','Ziehe dann die Komponenten des zweiten Vektors ab; der Faktor 2 gilt nicht für diesen zweiten Vektor.'])
    concept('G03',k+4,'Ein von 0 verschiedener Vektor wird mit '+str(-n)+' multipliziert. Was ändert sich?', 'Seine Länge wird '+str(n)+'-mal so groß und seine Richtung kehrt sich um.','Nur die Richtung ändert sich, die Länge bleibt immer gleich.','Seine Länge wird negativ.','Der Betrag des Faktors skaliert die Länge.','Das negative Vorzeichen dreht die Richtung um. Eine geometrische Länge bleibt trotzdem nichtnegativ.')
    calc('G04',k,'Welche Länge hat '+m(M([n,0,0]))+'?',n,[-n,n*n],length_steps([n,0,0]))
    calc('G04',k+2,'Wie weit sind '+m(r'A(0\mid 1\mid 2)')+' und '+m(r'B('+str(n)+r'\mid '+str(v+1)+r'\mid 2)')+' voneinander entfernt?',S.sqrt(n*n+v*v),[n+v,n*n+v*v],point_distance_steps([0,1,2],[n,v+1,2]))
    concept('G04',k+4,'Ein Vektor hat die Länge '+str(n)+'. Welcher Faktor macht daraus einen Einheitsvektor gleicher Richtung?',m(R(1,n)),str(n),str(-n),'Zum Normieren gilt '+m(r'\vec e=\frac{\vec v}{\lVert\vec v\rVert}')+' für '+m(r'\vec v\ne0')+'. Ein Einheitsvektor soll die Länge 1 haben.','Hier ist die Länge '+str(n)+', also teilst du jede Komponente durch '+str(n)+'. Der Faktor ist '+m(R(1,n))+'. Ein negativer Faktor würde zusätzlich die Richtung umkehren.')
    concept('G05',k,'Was gilt für '+m(M([1,2,0]))+' und '+m(M([n,2*n,0]))+'?', 'Sie sind linear abhängig, denn der zweite ist das '+str(n)+'-Fache des ersten.','Sie sind unabhängig, weil ihre Längen verschieden sind.','Sie sind orthogonal.','Alle Komponenten wurden mit demselben Faktor multipliziert.','Damit zeigen sie in dieselbe Richtung; verschiedene Längen verhindern Kollinearität nicht.')
    calc('G05',k+2,'Für welchen Wert a sind '+m(M([1,2,0]))+' und '+m(M([n,a,0]))+' kollinear?',2*n,[n,R(n,2)],['Aus der ersten Komponente folgt der gemeinsame Faktor '+str(n)+'.','Derselbe Faktor muss auch in der zweiten Komponente gelten: a = 2 · '+str(n)+'.'])
    concept('G05',k+4,'Zu '+m(M([1,0,0]))+' und '+m(M([0,1,0]))+' kommt '+m(M([n,v,0]))+' hinzu. Warum sind die drei Vektoren abhängig?', 'Der dritte lässt sich als Linearkombination der ersten beiden darstellen.','Weil jeder der drei Vektoren ein Nullvektor ist.','Weil im Raum nie drei unabhängige Vektoren existieren.','Multipliziere den ersten mit '+str(n)+' und den zweiten mit '+str(v)+'.','Ihre Summe ist genau der dritte Vektor. Allgemein können im Raum durchaus drei unabhängige Vektoren existieren.')
    calc('G06',k,'Berechne das Skalarprodukt '+m(M([n,1,0]))+' · '+m(M([1,v,2]))+'.',n+v,[n*v,n-v],['Multipliziere die passenden Komponenten.','Addiere die Produkte: '+str(n)+' · 1 + 1 · '+str(v)+' + 0 · 2.'])
    calc('G06',k+2,'Welche Zahl ergibt '+m(M([n,-v,1]))+' im Skalarprodukt mit sich selbst?',n*n+v*v+1,[S.sqrt(n*n+v*v+1),n*n-v*v+1],['Ein Skalarprodukt mit sich selbst ist die Summe der Komponentenquadrate.','Auch die negative Komponente liefert ein positives Quadrat; das Ergebnis ist das Quadrat der Länge.'])
    concept('G06',k+4,'Zwei Vektoren haben das Skalarprodukt −'+str(n)+'. Was folgt für ihren eingeschlossenen Winkel?', 'Der Winkel ist größer als 90° und höchstens 180°.','Der Winkel ist zwingend genau 90°.','Der Winkel ist kleiner als 90°.','Ein negatives Skalarprodukt bedeutet einen negativen Kosinus, weil beide Längen positiv sind.','Für Winkel zwischen 0° und 180° ist der Kosinus genau oberhalb von 90° negativ. Gegenläufige Vektoren mit 180° sind möglich.')
    calc('G07',k,'Welchen Wert muss a haben, damit '+m(M([1,n,0]))+' und '+m(M([a,1,0]))+' orthogonal sind?',-n,[n,0],['Senkrechte Vektoren haben das Skalarprodukt 0.','Hier steht a + '+str(n)+' = 0. Löse diese Gleichung.'])
    concept('G07',k+2,'Welcher Vektor steht senkrecht auf '+m(M([n,v,0]))+'?',m(M([v,-n,1])),m(M([v,n,1])),m(M([n,v,1])),'Berechne für jeden Kandidaten das Skalarprodukt.','Beim Vektor mit Komponenten (' + str(v) + '|−' + str(n) + '|1) heben sich die beiden Produkte auf; die dritte Komponente des Ausgangsvektors ist 0.')
    concept('G07',k+4,'Der Nullvektor hat mit '+m(M([n,v,1]))+' das Skalarprodukt 0. Was gilt für die Winkelberechnung?', 'Ein Winkel zum Nullvektor ist nicht definiert.','Der Winkel ist deshalb sicher 90°.','Der Winkel ist deshalb sicher 0°.','In der Winkelformel steht das Produkt der Vektorlängen im Nenner.','Die Länge des Nullvektors ist 0. Durch 0 darfst du nicht teilen, und der Nullvektor hat keine Richtung.')
    calc('G08',k,'Welchen Winkel bilden '+m(M([n,0,0]))+' und '+m(M([0,v,0]))+'? Gib Grad an.',90,[0,180],['Das Skalarprodukt der beiden von 0 verschiedenen Vektoren ist 0.','Damit sind sie orthogonal.'])
    calc('G08',k+2,'Für '+m(M([1,0,0]))+' und '+m(M([n,v,0]))+': Wie groß ist der Kosinus des Winkels?',n/S.sqrt(n*n+v*v),[v/S.sqrt(n*n+v*v),n/(n*n+v*v)],['Teile das Skalarprodukt durch das Produkt der Längen.','Die erste Länge ist 1, die zweite √('+str(n*n+v*v)+').'])
    concept('G08',k+4,'Ein Vektor u wird mit −'+str(n)+' multipliziert und bildet mit sich selbst zuvor den Winkel 0°. Welchen Winkel bilden u und der neue Vektor?', '180°.','0°.','90°.','Ein negativer Faktor kehrt die Richtung eines von 0 verschiedenen Vektors um.','Die beiden Pfeile sind gegenläufig. Winkel zwischen Vektoren und kleinerer Winkel zwischen Geraden sind zu unterscheiden.')
    concept('G09',k,'Welche Aussage zu '+m(r'g:\vec x='+L(M([n,1,0]))+r'+t'+L(M([0,v,1])))+' stimmt?', 'Der erste Vektor zeigt zu einem Punkt auf g, der zweite gibt die Richtung an.','Der erste Vektor ist zwingend der Normalenvektor von g.','Der Parameter t muss immer positiv sein.','Setzt du t = 0, erhältst du den Stützpunkt.','Der Parameter einer ganzen Geraden darf jeden reellen Wert annehmen.')
    calc('G09',k+2,'Eine Gerade geht durch '+m(r'A(1\mid 0\mid 2)')+' und '+m(r'B('+str(n)+r'\mid '+str(v)+r'\mid 3)')+'. Welcher Vektor kann ihre Richtung beschreiben?',M([n-1,v,1]),[M([n+1,v,5]),M([n-1,-v,1])],['Bilde den Verbindungsvektor vom ersten zum zweiten Punkt.','Jedes von 0 verschiedene Vielfache dieses Vektors wäre ebenfalls als Richtung erlaubt.'])
    concept('G09',k+4,'In einer Parameterdarstellung wird der Richtungsvektor mit '+str(n)+' multipliziert. t darf weiterhin alle reellen Werte annehmen. Was ändert sich an der Geraden?', 'Die Punktmenge bleibt gleich; nur die Parametrisierung ändert sich.','Die Gerade hat plötzlich nur noch endlich viele Punkte.','Die Gerade verschiebt sich um '+str(n)+' Einheiten.','Jeder bisherige Parameterwert kann durch einen entsprechend skalierten neuen Parameter ersetzt werden.','Ein von 0 verschiedener Faktor ändert die Richtungslinie und den Stützpunkt nicht.')
    calc('G10',k,'Für '+m(r'g:\vec x=(1\mid 2\mid 0)+t(1\mid 0\mid 1)')+': Welcher Parameter liefert den Punkt '+m(r'P('+str(n+1)+r'\mid 2\mid '+str(n)+r')')+'?',n,[n+1,n-1],['Vergleiche alle drei Koordinaten.','Aus der dritten Koordinate folgt direkt t = '+str(n)+'. Prüfe auch die erste und die konstante zweite Koordinate.'])
    calc('G10',k+2,'Für '+m(r'g:\vec x=(0\mid 0\mid '+str(n)+r')+t(1\mid 2\mid -1)')+': Bei welchem Parameter schneidet g die xy-Ebene?',n,[-n,0],['In der xy-Ebene ist die z-Koordinate 0.','Setze '+str(n)+' − t = 0. Die anderen beiden Koordinaten schränken diese Ebene nicht ein.'])
    concept('G10',k+4,'Für die Punktprobe auf einer Geraden ergeben die x-Gleichung t = '+str(n)+' und die y-Gleichung t = '+str(v)+'. Was folgt?', 'Der Punkt liegt nicht auf der Geraden, weil ein gemeinsamer Parameter nötig ist.','Der Punkt liegt auf g, weil zwei Parameterwerte gefunden wurden.','Es reicht, nur die x-Koordinate zu prüfen.','Ein Punkt der Geraden entsteht durch genau eine gemeinsame Wahl von t für alle Koordinaten.','Verschiedene, widersprüchliche t-Werte können daher keine erfolgreiche Punktprobe sein.')
    concept('G11',k,'Zwei Geraden haben Richtungsvektoren u und '+m(n*S.Symbol('u'))+'. Was kannst du ohne Punktprobe folgern?', 'Sie sind parallel oder identisch.','Sie sind sicher echt parallel.','Sie sind sicher windschief.','Die Richtungsvektoren sind Vielfache voneinander.','Das entscheidet die Richtung, aber noch nicht, ob die Geraden dieselben Punkte enthalten.')
    concept('G11',k+2,'Die Gerade '+m(r'g:\vec x=t(1\mid 2\mid 0)')+' und '+m(r'h:\vec x=('+str(n)+r'\mid '+str(2*n)+r'\mid 0)+s(2\mid 4\mid 0)')+' sind ...','identisch.','echt parallel.','windschief.','Die Richtungsvektoren sind kollinear.','Der Stützpunkt von h liegt für t = '+str(n)+' auf g. Gleiche Richtung plus gemeinsamer Punkt ergibt Identität.')
    concept('G11',k+4,'Beide Geraden haben Richtung '+m(M([1,0,0]))+'. Ihre Stützpunkte haben y = 0 beziehungsweise y = '+str(n)+', jeweils z = 0. Welche Lage ist sicher?', 'Echt parallel.','Identisch, weil ihre Richtungen gleich sind.','Sie schneiden sich bei einer negativen Parameterwahl.','Die y-Koordinate ändert sich auf keiner der Geraden.','Wegen der unterschiedlichen konstanten y-Werte gibt es keinen gemeinsamen Punkt, auch nicht bei negativen Parametern.')
    calc('G12',k,'Für '+m(r'g:\vec x=(t\mid 0\mid 0)')+' und '+m(r'h:\vec x=('+str(n)+r'\mid s\mid 0)')+': Welcher Schnittpunkt entsteht?',M([n,0,0]),[M([0,n,0]),M([n,n,0])],['Setze die passenden Koordinaten gleich: t = '+str(n)+' und s = 0.','Setze die Parameter in eine der Geraden ein und prüfe den Punkt auf der anderen.'])
    calc('G12',k+2,'Für '+m(r'g:\vec x=(t\mid t\mid 0)')+' und '+m(r'h:\vec x=(0\mid '+str(2*n)+r'\mid 0)+s(1\mid -1\mid 0)')+': Wie groß ist t im Schnittpunkt?',n,[2*n,-n],['Aus der ersten Koordinate folgt t = s.','In der zweiten steht t = '+str(2*n)+' − s. Einsetzen ergibt 2t = '+str(2*n)+'.'])
    concept('G12',k+4,'Beim Gleichsetzen zweier Raumgeraden ergeben zwei Koordinaten t = '+str(n)+' und s = '+str(v)+'. Die dritte Gleichung ist damit falsch. Was folgt?', 'Die gefundenen Werte liefern keinen Schnittpunkt.','Zwei passende Koordinaten reichen immer für einen Schnittpunkt.','Man darf die dritte Koordinate mitteln.','Ein Schnittpunkt muss alle drei Koordinatengleichungen erfüllen.','Die dritte Gleichung ist kein zusätzlicher Wunsch, sondern Teil der Punktgleichheit. Die übrige Lage muss separat untersucht werden.')
    concept('G13',k,'Zwei Geraden im Raum sind nicht parallel und haben keinen gemeinsamen Punkt. Welche Lage haben sie?', 'Windschief.','Identisch.','Echt parallel.','Die Richtung schließt Parallelität und Identität aus.','Im Raum gibt es zusätzlich zu schneidenden Geraden die Möglichkeit, aneinander vorbeizulaufen: windschief.')
    concept('G13',k+2,'Wie liegen '+m(r'g:\vec x=t(1\mid 0\mid 0)')+' und '+m(r'h:\vec x=(0\mid 0\mid '+str(n)+r')+s(0\mid 1\mid 0)')+'?', 'Windschief.','Sie schneiden sich im Ursprung.','Sie sind parallel.','Ihre Richtungen sind unabhängig, also nicht parallel.','Auf g ist z = 0, auf h ist z = '+str(n)+'. Deshalb gibt es keinen gemeinsamen Punkt.')
    concept('G13',k+4,'Ein Schüler sieht verschiedene Stützpunkte und erklärt zwei Geraden mit kollinearen Richtungen für windschief. Welche Korrektur passt?', 'Kollineare Richtungen schließen Windschiefe aus; es fehlt eine Punktprobe auf Identität.','Verschiedene Stützpunkte beweisen Windschiefe.','Gleiche Richtungen beweisen einen eindeutigen Schnittpunkt.','Verschiedene Stützpunkte können sogar dieselbe Gerade beschreiben.','Prüfe bei gleicher Richtung, ob ein Stützpunkt auf der anderen Geraden liegt. Die Lage ist identisch oder echt parallel.')
    calc('G14',k,'Welchen kleineren Winkel bilden Geraden mit Richtungen '+m(M([1,0,0]))+' und '+m(M([-n,0,0]))+'? Gib Grad an.',0,[180,90],['Gegenläufige Richtungsvektoren gehören trotzdem zu parallelen Geraden.','Der kleinere Winkel der Richtungslinien ist daher 0°, nicht 180°.'])
    calc('G14',k+2,'Für Geraden mit Richtungen '+m(M([1,0,0]))+' und '+m(M([-n,v,0]))+': Wie groß ist der Kosinus ihres kleineren Winkels?',n/S.sqrt(n*n+v*v),[-n/S.sqrt(n*n+v*v),v/S.sqrt(n*n+v*v)],['Für den kleineren Geradenwinkel verwendest du den Betrag des Skalarprodukts.','Teile diesen durch das Produkt der beiden Längen.'])
    concept('G14',k+4,'Eine Gerade bekommt statt ihres Richtungsvektors v den Vektor −'+str(n)+'v. Wie ändert sich ihr kleinerer Winkel zu einer anderen Geraden?', 'Er bleibt unverändert.','Er wird immer zu 180° minus dem alten kleineren Winkel.','Er wird '+str(n)+'-mal so groß.','Die geometrische Gerade ändert sich durch diesen Faktor nicht.','In der Formel für den kleineren Winkel kürzt sich der Betrag des Faktors zwischen Zähler und Nenner heraus.')
    calc('G15',k,'Löse das LGS '+m(r'x+y='+str(n+v)+r',\quad x-y='+str(n-v))+'. Gib x an.',n,[v,n+v],['Addiere die beiden Gleichungen. Dabei fällt y weg.','Es bleibt 2x = '+str(2*n)+'. Teile durch 2.'])
    concept('G15',k+2,'Im Gauß-Verfahren entsteht die Zeile '+m(r'0='+str(n))+'. Was bedeutet das?', 'Das LGS ist widersprüchlich und hat keine Lösung.','Es gibt unendlich viele Lösungen.','Alle Variablen müssen 0 sein.','Eine von 0 verschiedene Zahl kann nicht gleich 0 sein.','Jede Lösung müsste auch diese Zeile erfüllen. Weil das unmöglich ist, ist die gesamte Lösungsmenge leer.')
    concept('G15',k+4,'Ein LGS in drei Variablen ist widerspruchsfrei und hat nach Gauß nur zwei unabhängige Pivotzeilen. Was folgt?', 'Mindestens eine freie Variable und unendlich viele Lösungen.','Eine eindeutige Lösung, weil keine Widerspruchszeile entsteht.','Keine Lösung wegen der fehlenden dritten Zeile.','Drei Variablen bei nur zwei unabhängigen Gleichungen lassen einen Freiheitsgrad.','Ohne Widerspruch kann der freie Parameter beliebig gewählt werden. Keine Widerspruchszeile allein garantiert noch keine Eindeutigkeit.')
    concept('G16',k,'Welche Voraussetzung brauchen zwei Spannvektoren einer Ebene mit Stützpunkt '+m(r'P('+str(n)+r'\mid 0\mid 1)')+'?', 'Sie müssen linear unabhängig sein.','Sie müssen dieselbe Richtung haben.','Beide müssen die Länge 1 haben.','Zwei parallele Spannvektoren liefern nur eine Richtung und damit keine Ebene.','Eine Ebene braucht zwei unabhängige Richtungen; ihre Längen sind dafür nicht entscheidend.')
    calc('G16',k+2,'Die Ebene hat Stützpunkt '+m(r'A(1\mid 0\mid 0)')+' und Spannvektoren '+m(M([0,1,0]))+' und '+m(M([0,0,1]))+'. Welches Tupel erhältst du für r = '+str(n)+' und s = '+str(v)+'?',M([1,n,v]),[M([n,1,v]),M([1,v,n])],['Setze die Parameter in die zugehörigen Spannrichtungen ein.','Addiere beide skalierten Richtungsvektoren zum Stützvektor.'])
    concept('G16',k+4,'In einer Ebenenbeschreibung sind die Spannvektoren '+m(M([1,n,0]))+' und '+m(M([2,2*n,0]))+'. Was ist das Problem?', 'Die Darstellung beschreibt nur eine Gerade, weil die Spannvektoren abhängig sind.','Die beiden Vektoren dürfen keine unterschiedlichen Längen haben.','Der Stützpunkt müsste immer der Ursprung sein.','Der zweite Vektor ist genau das Doppelte des ersten.','Auch zwei frei wählbare Parameter erzeugen damit nur eine unabhängige Richtung.')
    calc('G17',k,'Welcher Normalenvektor lässt sich aus '+m(r'E:'+str(n)+r'x-y+2z=1')+' direkt ablesen?',M([n,-1,2]),[M([n,1,2]),M([1,-1,n])],['In der Koordinatenform sind die Koeffizienten von x, y und z die Komponenten eines Normalenvektors.','Nimm das Minus vor y mit; die rechte Seite gehört nicht zum Vektor.'])
    concept('G17',k+2,'Ein Normalenvektor n soll zu einer Ebene mit Spannvektoren u und v gehören. Welche Prüfung ist nötig?',m(r'n\cdot u=0\quad\text{und}\quad n\cdot v=0,\quad n\ne0'),m(r'n=u+v'),m(r'n\cdot u=0\text{ allein genügt}'),'Ein Normalenvektor steht senkrecht auf jeder Richtung der Ebene.','Bei zwei unabhängigen Spannrichtungen musst du deshalb beide Skalarprodukte prüfen; der Nullvektor wäre keine geeignete Normale.')
    concept('G17',k+4,'Die Ebene geht durch '+m(r'P('+str(n)+r'\mid 0\mid 0)')+' mit Normalenvektor '+m(M([1,2,0]))+'. Welche Normalenform passt?',m(r'(\vec x-('+str(n)+r',0,0))\cdot(1,2,0)=0'),m(r'(\vec x+('+str(n)+r',0,0))\cdot(1,2,0)=0'),m(r'\vec x\cdot('+str(n)+r',0,0)=1'),'Der Vektor vom Stützpunkt zu jedem Ebenenpunkt ist x − P.','Er muss senkrecht auf n stehen. Deshalb ist genau sein Skalarprodukt mit n gleich 0.')
    concept('G18',k,'Welche Koordinatengleichung gehört zur Ebene '+m(r'\vec x=('+str(n)+r'\mid 0\mid 0)+r(0\mid 1\mid 0)+s(0\mid 0\mid 1)')+'?',m(r'x='+str(n)),m(r'y='+str(n)),m(r'z='+str(n)),'Die Spannvektoren ändern nur die zweite und dritte Koordinate.','Die erste Koordinate bleibt bei jedem Punkt '+str(n)+'. Die beiden übrigen sind frei.')
    calc('G18',k+2,'Eine Ebene hat Normale '+m(M([1,2,1]))+' und enthält '+m(r'P('+str(n)+r'\mid '+str(v)+r'\mid 0)')+'. Welcher Wert d gehört zur Form '+m(r'x+2y+z=d')+'?',n+2*v,[n+v,n-2*v],['Setze die Koordinaten des bekannten Punktes in die linke Seite ein.','Der so berechnete Wert muss die rechte Seite der Ebene sein.'])
    concept('G18',k+4,'Die Gleichung '+m(r'x+2y-z='+str(n))+' wird vollständig mit '+str(v)+' multipliziert. Welche Ebene entsteht?', 'Dieselbe Ebene, da die ganze Gleichung mit einem von 0 verschiedenen Faktor multipliziert wird.','Eine parallele Ebene im Abstand '+str(v)+'.','Eine Ebene mit anderem Normalenwinkel.','Jeder Punkt erfüllt die neue Gleichung genau dann, wenn er die alte erfüllt.','Der Normalenvektor wird zwar skaliert, seine Richtungslinie und die Punktmenge ändern sich nicht.')
    concept('G19',k,'Liegt '+m(r'P('+str(n)+r'\mid '+str(v)+r'\mid 1)')+' auf '+m(r'E:x+y+z='+str(n+v+1))+'?', 'Ja, alle eingesetzten Koordinaten erfüllen die Gleichung.','Nein, weil z ungleich 0 ist.','Nein, weil ein Punkt drei und die Gleichung nur eine rechte Seite hat.','Setze die drei Koordinaten für x, y und z ein.','Die Summe ist '+str(n+v+1)+' und stimmt mit der rechten Seite überein.')
    calc('G19',k+2,'Wo schneidet '+m(r'E:x+2y+3z='+str(3*n))+' die z-Achse? Gib die z-Koordinate an.',n,[3*n,0],['Auf der z-Achse sind x und y gleich 0.','Es bleibt 3z = '+str(3*n)+'. Löse nach z auf.'])
    concept('G19',k+4,'Für die Ebene '+m(r'E:2x+y='+str(n))+' wird ein Spurpunkt auf der z-Achse gesucht. Welche Aussage ist richtig?', 'Es gibt keinen z-Achsen-Spurpunkt, weil dort die linke Seite 0 wäre.','Der Spurpunkt hat automatisch z = '+str(n)+'.','Die ganze z-Achse liegt in E.','Auf der z-Achse gilt x = y = 0, unabhängig von z.','Damit würde 0 = '+str(n)+' verlangt. Das ist unmöglich; auch eine beliebige z-Koordinate ändert daran nichts.')
    calc('G20',k,'Für '+m(r'g:\vec x=(0\mid 0\mid 1)+t(1\mid 0\mid 1)')+' und '+m(r'E:z='+str(n))+' wird der Schnittparameter t gesucht.',n-1,[n,n+1],['Die z-Koordinate der Geraden lautet 1 + t.','Setze sie gleich der Höhe der Ebene und ziehe 1 ab.'])
    calc('G20',k+2,'Für '+m(r'g:\vec x=(t\mid 2t\mid 0)')+' und '+m(r'E:x+y='+str(3*n))+' wird der Schnittpunkt gesucht.',M([n,2*n,0]),[M([3*n,6*n,0]),M([n,n,0])],['Setze die Geradenkoordinaten in die Ebene ein: t + 2t = '+str(3*n)+'.','Daraus folgt t = '+str(n)+'. Setze diesen Wert wieder in alle Geradenkoordinaten ein.'])
    concept('G20',k+4,'Beim Einsetzen einer Geraden in '+m(r'E:x+y+z='+str(n))+' entsteht die Identität '+m(r'0=0')+'. Was bedeutet das?', 'Jeder Punkt der Geraden liegt in der Ebene.','Es gibt genau einen Schnittpunkt mit t = 0.','Gerade und Ebene sind echt parallel ohne gemeinsame Punkte.','Eine Identität schränkt den Parameter nicht ein. Jeder reelle Wert erfüllt die Ebenenbedingung.','Die ganze Gerade ist daher enthalten; es gibt nicht nur einen einzelnen Schnittpunkt.')
    concept('G21',k,'Eine Gerade verläuft in konstanter Höhe z = '+str(n)+', die Ebene ist z = 0. Welche Lage haben sie?', 'Die Gerade ist echt parallel zur Ebene.','Die Gerade liegt vollständig in der Ebene.','Sie schneidet die Ebene für t = '+str(n)+'.','Die z-Koordinate der Geraden ändert sich nicht.','Kein Punkt erreicht die geforderte Höhe 0. Daher ist die Gerade parallel, aber nicht enthalten.')
    concept('G21',k+2,'Eine Gerade hat Stützpunkt in E und einen Richtungsvektor orthogonal zur Normalen von E. Welche Lage liegt vor?', 'Die Gerade liegt vollständig in E.','Die Gerade ist echt parallel ohne gemeinsamen Punkt.','Die Gerade schneidet E genau einmal.','Orthogonalität zur Normalen bedeutet, dass die Geradenrichtung parallel zur Ebene verläuft.','Weil zusätzlich ein Geradenpunkt in der Ebene liegt, bleibt die ganze Gerade in der Ebene.')
    concept('G21',k+4,'Zu einer Ebene mit Normale '+m(M([1,0,0]))+' gehört eine Gerade mit Richtung '+m(M([n,1,0]))+'. Warum gibt es genau einen Schnittpunkt?', 'Das Skalarprodukt aus Normale und Richtung ist ungleich 0; die Parametergleichung hat daher einen eindeutigen Wert.','Weil jede Gerade jede Ebene genau einmal schneidet.','Weil die Richtung nicht der Nullvektor ist.','Das Skalarprodukt ist '+str(n)+' und damit nicht 0.','Der Koeffizient von t in der eingesetzten Ebenengleichung verschwindet nicht. Eine lineare Gleichung mit diesem Koeffizienten hat genau eine Lösung.')
    concept('G22',k,'Welche Lage haben die Ebenen '+m(r'E:z='+str(n))+' und '+m(r'F:z='+str(n+v))+'?', 'Echt parallel.','Identisch.','Sie schneiden sich in der x-Achse.','Beide Ebenen haben dieselbe Normalenrichtung.','Wegen der verschiedenen festen z-Werte besitzen sie keinen gemeinsamen Punkt.')
    concept('G22',k+2,'Wie lautet die Schnittmenge der Ebenen '+m(r'E:x='+str(n))+' und '+m(r'F:y='+str(v))+'?',m(r'\vec x=('+str(n)+r'\mid '+str(v)+r'\mid 0)+t(0\mid 0\mid 1)'),m(r'\vec x=t(1\mid 1\mid 0)'), 'Die leere Menge.','Ein gemeinsamer Punkt muss gleichzeitig die erste und zweite feste Koordinate besitzen.','Die z-Koordinate ist frei. So entsteht eine Gerade parallel zur z-Achse.')
    concept('G22',k+4,'Die Normalen zweier Ebenen sind keine Vielfachen voneinander. Welche Lage folgt im dreidimensionalen Raum?', 'Sie schneiden sich in einer Geraden.','Sie schneiden sich in genau einem einzelnen Punkt.','Sie sind echt parallel.','Nicht kollineare Normalen schließen parallele oder identische Ebenen aus.','Zwei unabhängige lineare Ebenenbedingungen lassen im Raum eine freie Richtung übrig: ihre Schnittgerade.')
    calc('G23',k,'Welchen kleineren Winkel bilden Ebenen mit Normalen '+m(M([n,0,0]))+' und '+m(M([0,v,0]))+'? Gib Grad an.',90,[0,180],['Der kleinere Ebenenwinkel entspricht dem kleineren Winkel der Normalenrichtungen.','Die Normalen sind orthogonal, weil ihr Skalarprodukt 0 ist.'])
    calc('G23',k+2,'Für Ebenennormalen '+m(M([1,0,0]))+' und '+m(M([n,v,0]))+': Wie groß ist der Kosinus des kleineren Ebenenwinkels?',n/S.sqrt(n*n+v*v),[v/S.sqrt(n*n+v*v),n/(n*n+v*v)],['Nutze den Betrag des Normalen-Skalarprodukts.','Teile durch das Produkt der Längen; die erste Länge ist 1.'])
    concept('G23',k+4,'Eine Ebenengleichung wird mit −'+str(n)+' multipliziert. Wie ändert sich ihr kleinerer Winkel zu einer festen zweiten Ebene?', 'Der Winkel bleibt gleich.','Der Winkel wird negativ.','Der Winkel wird zwingend durch 180° minus den bisherigen kleineren Winkel ersetzt.','Die Punktmenge der Ebene bleibt dieselbe.','Die Normale kehrt zwar ihre Orientierung um, in der Formel für den kleineren Winkel wird das durch den Betrag ausgeglichen.')
    calc('G24',k,'Eine Gerade hat dieselbe Richtung wie ein Normalenvektor der Ebene. Welchen Winkel bildet sie mit der Ebene? Gib Grad an.',90,[0,45],['Ein Normalenvektor steht senkrecht auf der Ebene.','Eine dazu parallele Gerade ist daher ebenfalls senkrecht zur Ebene.'])
    calc('G24',k+2,'Geradenrichtung '+m(M([1,0,0]))+', Ebenennormale '+m(M([n,v,0]))+': Wie groß ist der Sinus des kleineren Gerade-Ebene-Winkels?',n/S.sqrt(n*n+v*v),[v/S.sqrt(n*n+v*v),-n/S.sqrt(n*n+v*v)],['Für den Winkel zur Ebene brauchst du den Sinus, weil die Normale senkrecht zur Ebene steht.','Teile den Betrag des Skalarprodukts durch die Längen der Richtung und der Normalen.'])
    concept('G24',k+4,'Eine Rechnung liefert zwischen Geradenrichtung und Ebenennormale den kleineren Winkel '+str(20*v)+'°. Welchen Winkel bildet die Gerade mit der Ebene?',str(90-20*v)+'°',str(20*v)+'°',str(90+20*v)+'°','Der Winkel zur Ebene ergänzt den kleineren Winkel zur Normalen auf 90°.','Subtrahiere daher den berechneten Winkel von 90°; verwende nicht unverändert den Normalenwinkel.')
    calc('G25',k,'Welchen Abstand hat '+m(r'P('+str(n)+r'\mid '+str(v)+r'\mid 0)')+' von der x-Achse?',v,[n,n+v],['Der nächste Punkt auf der x-Achse hat denselben x-Wert und die übrigen Koordinaten 0.','Die einzige nicht verschwindende senkrechte Änderung ist hier die y-Koordinate.'])
    calc('G25',k+2,'Die Gerade ist '+m(r'g:\vec x=t(1\mid 1\mid 0)')+'. Wie weit ist '+m(r'P('+str(n)+r'\mid 0\mid 0)')+' von g entfernt?',n/S.sqrt(2),[n,n*S.sqrt(2)],['Der Lotfuß hat Parameter t = (P · v)/(v · v) = '+str(n)+'/2.','Ziehe den Lotfuß von P ab und berechne die Länge. Beide nicht verschwindenden Differenzen haben den Betrag '+str(n)+'/2.'])
    concept('G25',k+4,'Der Abstand eines Punktes zur Geraden wird minimiert. Welche Bedingung muss der Verbindungsvektor vom Lotfuß zum Punkt erfüllen?', 'Er ist orthogonal zum Richtungsvektor der Geraden.','Er ist immer parallel zum Richtungsvektor.','Seine Länge muss der Parameterzahl '+str(n)+' entsprechen.','Am nächsten Geradenpunkt ist der Verbindungsweg senkrecht zur Geraden.','Mit dem Skalarprodukt 0 kannst du den Lotfußparameter bestimmen. Die Länge ist erst danach zu berechnen.')
    calc('G26',k,'Wie weit ist '+m(r'P(1\mid 2\mid '+str(n)+r')')+' von der Ebene z = 0 entfernt?',n,[n*n,0],['Die Ebene ist die xy-Ebene.','Der senkrechte Weg ändert nur die z-Koordinate; nimm ihren nichtnegativen Betrag.'])
    calc('G26',k+2,'Welchen Abstand hat der Ursprung von '+m(r'E:'+str(n)+r'x= '+str(n*v))+'?',v,[n*v,R(v,n)],['Teile die ganze Ebenengleichung durch '+str(n)+'. Sie lautet dann x = '+str(v)+'.','Der Ursprung liegt in x-Richtung genau '+str(v)+' Einheiten entfernt; alternativ normierst du durch die Länge der Normalen.'])
    concept('G26',k+4,'Beim Punkt-Ebene-Abstand wird der Betrag des Einsetzergebnisses durch die Länge des Normalenvektors geteilt. Warum ist das nötig?', 'Damit eine Skalierung der gesamten Ebenengleichung den Abstand nicht ändert.','Weil geometrische Abstände immer kleiner als 1 sein müssen.','Damit die rechte Seite jeder Ebene zu 0 wird.','Eine Ebenengleichung kann mit jeder von 0 verschiedenen Zahl multipliziert werden, ohne die Ebene zu ändern.','Zähler und Normalenlänge skalieren dabei mit demselben Betrag. Nur ihr Quotient beschreibt einen geometrisch eindeutigen Abstand.')
    calc('G27',k,'Welchen Abstand haben die parallelen Ebenen z = '+str(n)+' und z = '+str(n+v)+'?',v,[2*n+v,n+v],['Beide Ebenen unterscheiden sich nur in ihrer Höhe.','Der senkrechte Abstand ist der Betrag der Differenz beider z-Werte.'])
    calc('G27',k+2,'Bestimme den Abstand zwischen '+m(r'E:2x= '+str(2*n))+' und '+m(r'F:4x= '+str(4*(n+v)))+'.',v,[2*v,4*v],['Bringe beide Gleichungen zuerst in eine vergleichbare normierte Form.','Es entstehen x = '+str(n)+' und x = '+str(n+v)+'. Die rechten Seiten der ursprünglichen unnormierten Gleichungen darfst du nicht direkt subtrahieren.'])
    concept('G27',k+4,'Zwei Ebenen sind identisch, obwohl die Koeffizienten der einen Gleichung das '+str(n)+'-Fache der anderen sind. Welchen Abstand haben sie?', '0.','Den Faktor '+str(n)+'.','Der Abstand ist nicht definiert, weil die Gleichungen verschieden aussehen.','Identische Ebenen enthalten dieselben Punkte.','Der Abstand einer Punktmenge zu sich selbst ist 0; verschiedene Schreibweisen ändern die Geometrie nicht.')
    calc('G28',k,'Die Geraden '+m(r'g:\vec x=t(1\mid 0\mid 0)')+' und '+m(r'h:\vec x=(0\mid '+str(n)+r'\mid 0)+s(1\mid 0\mid 0)')+' sind parallel. Welchen Abstand haben sie?',n,[n*n,0],['Die beiden Geraden haben unterschiedliche konstante y-Werte.','Der kürzeste Weg verläuft senkrecht zu ihrer gemeinsamen x-Richtung und hat die Länge der y-Differenz.'])
    calc('G28',k+2,'Die Geraden '+m(r'g:\vec x=t(1\mid 0\mid 0)')+' und '+m(r'h:\vec x=(0\mid 0\mid '+str(n)+r')+s(0\mid 1\mid 0)')+' sind windschief. Wie groß ist ihr Abstand?',n,[2*n,0],['Jeder Verbindungsweg enthält die feste z-Differenz '+str(n)+'. Ein kürzerer Abstand ist daher unmöglich.','Für t = s = 0 bleiben nur diese z-Einheiten übrig; dieser Weg ist zu beiden Richtungen senkrecht.'])
    concept('G28',k+4,'Zum Abstand windschiefer Geraden wird nur die Länge zwischen ihren Stützpunkten berechnet. Welche Aussage ist korrekt?', 'Das ist nur eine obere Schranke; minimal wird der gemeinsame senkrechte Verbindungsweg.','Jedes Paar von Stützpunkten hat bereits den minimalen Abstand.','Windschiefe Geraden haben definitionsgemäß Abstand 0.','Die Wahl der Stützpunkte ist bei derselben Geraden nicht eindeutig. Ihre Entfernung kann daher kein automatisch eindeutiger Geradenabstand sein.','Der minimale Verbindungsvektor muss orthogonal zu beiden Richtungsvektoren sein.')
    calc('G29',k,'Ein rechtwinkliges Dreieck hat Katheten '+str(n)+' und '+str(v)+'. Wie groß ist sein Flächeninhalt?',R(n*v,2),[n*v,n+v],['Die beiden senkrechten Seiten können Grundseite und Höhe sein.','Das Dreieck hat die halbe Fläche des zugehörigen Rechtecks.'])
    calc('G29',k+2,'Ein Parallelogramm wird von '+m(M([n,0,0]))+' und '+m(M([1,v,0]))+' aufgespannt. Welche Fläche hat es?',n*v,[n*S.sqrt(1+v*v),R(n*v,2)],['Wähle den ersten Vektor als Grundseite mit Länge '+str(n)+'.','Die senkrechte Höhe ist die y-Komponente '+str(v)+', nicht die Länge des schrägen zweiten Vektors.'])
    concept('G29',k+4,'Die Seitenvektoren eines Parallelogramms sind beide von 0 verschieden, aber kollinear. Was folgt für seine Fläche?', 'Sie ist 0, weil keine zweite unabhängige Richtung entsteht.','Sie ist das Produkt beider Vektorlängen.','Sie ist immer positiv, weil beide Seiten Längen besitzen.','Die beiden Seiten liegen auf derselben Richtungslinie.','Die senkrechte Höhe und der Betrag ihres Kreuzprodukts sind daher 0. Das Parallelogramm ist entartet.')
    calc('G30',k,'Ein Quader hat Kanten '+str(n)+', '+str(v)+' und 2. Welches Volumen hat er?',2*n*v,[n+v+2,n*v],['Das Volumen ist Länge mal Breite mal Höhe.','Multipliziere alle drei Kantenlängen; die Einheit ist eine Kubikeinheit.'])
    calc('G30',k+2,'Eine Pyramide hat Grundfläche '+str(n*v)+' und senkrechte Höhe 3. Welches Volumen hat sie?',n*v,[3*n*v,R(n*v,3)],['Eine Pyramide hat ein Drittel des Volumens des Prismas mit gleicher Grundfläche und Höhe.','Rechne Grundfläche mal Höhe und teile durch 3.'])
    concept('G30',k+4,'Drei Spatvektoren liegen in derselben Ebene. Was folgt unabhängig von ihren Längen für das Spatvolumen?', 'Es beträgt 0, weil die räumliche Höhe fehlt.','Es ist stets das Produkt aller drei Längen.','Es beträgt mindestens '+str(n)+' Kubikeinheiten.','Koplanare Vektoren können keinen dreidimensionalen Körper mit positiver Höhe aufspannen.','Das zugehörige Spatprodukt beziehungsweise die Determinante ist 0.')
    calc('G31',k,'Spiegle '+m(r'P(1\mid 2\mid '+str(n)+r')')+' an der xy-Ebene. Welches Tupel entsteht?',M([1,2,-n]),[M([-1,-2,n]),M([1,2,0])],['Die Ebene hat z = 0.','Wechsle nur das Vorzeichen der z-Koordinate; der Punkt in der Ebene wäre der Lotfuß, nicht der Spiegelpunkt.'])
    calc('G31',k+2,'Spiegle '+m(r'P(1\mid 2\mid '+str(n+v)+r')')+' an der Ebene z = '+str(n)+'. Welches Tupel entsteht?',M([1,2,n-v]),[M([1,2,-n-v]),M([1,2,n])],['Der Ausgangspunkt liegt '+str(v)+' Einheiten oberhalb der Ebene.','Der Bildpunkt liegt ebenso weit darunter; die Ebene liegt genau in der Mitte der Verbindung.'])
    concept('G31',k+4,'L ist der Lotfuß eines Punktes P auf einer Ebene. Welche Gleichung liefert den gespiegelten Punkt P′?',m(r'P\prime=2L-P'),m(r'P\prime=L'),m(r'P\prime=2P-L'),'Beim Spiegeln geht es von P zuerst nach L und um denselben Vektor noch einmal weiter.','Also P′ = P + 2(L − P) = 2L − P. Der Lotfuß ist nur die Mitte des Weges.')
    calc('G32',k,'Ein Objekt bewegt sich mit dem konstanten Geschwindigkeitsvektor '+m(M([n,0,0]))+' in Metern pro Sekunde. Welche Geschwindigkeit hat es in m/s?',n,[n*n,1],['Die Geschwindigkeit als Zahl ist die Länge des Geschwindigkeitsvektors. Seine Komponenten sind in m/s angegeben.']+length_steps([n,0,0]))
    calc('G32',k+2,'Eine Drohne startet bei '+m(r'P(0\mid 0\mid '+str(n)+r')')+' und hat '+m(r'z(t)='+str(n)+r'-'+str(v)+r't')+' für '+m(r't\ge0')+'. Wann erreicht sie die Ebene z = 0?',R(n,v),[n*v,-R(n,v)],['Setze die Höhe gleich 0 und löse die lineare Gleichung.','Der gefundene Zeitpunkt ist nichtnegativ und gehört zum betrachteten Flugabschnitt.'])
    concept('G32',k+4,'Eine Straßenstrecke wird durch '+m(r'P(t)=A+t(B-A),\quad 0\le t\le1')+' beschrieben. Die verlängerte Gerade schneidet eine Ebene bei t = '+str(n)+'. Was folgt für die Strecke?', 'Dieser Schnittpunkt liegt nicht auf dem modellierten Streckenabschnitt.','Jeder Geradenschnitt ist automatisch ein Streckenschnitt.','Der Punkt muss der Mittelpunkt der Strecke sein.','Der Parameter liegt außerhalb des erlaubten Intervalls von 0 bis 1.','Die geometrische Gerade ist unbeschränkt, die Straße in diesem Modell aber nur das Stück zwischen A und B.')
    concept('G33',k,'Eine Gerade hat die Richtung '+m(M([1,n,0]))+' und soll senkrecht auf der Ebene stehen. Wie muss ihre Richtung zur Ebenennormalen liegen?', 'Sie muss parallel zur Normalen sein.','Sie muss orthogonal zur Normalen sein.','Die Normalenrichtung spielt dafür keine Rolle.','Die Normale zeigt bereits senkrecht aus der Ebene heraus.','Eine dazu parallele Gerade steht ebenfalls senkrecht auf der Ebene. Orthogonalität zur Normalen würde eine parallele Ebenenrichtung bedeuten.')
    concept('G33',k+2,'Ein Punkt erfüllt zwei von drei Koordinatengleichungen einer Geraden. In der dritten gibt es einen Widerspruch. Wie beurteilst du den Nachweis?', 'Der Nachweis ist gescheitert; alle Koordinaten müssen zugleich passen.','Zwei Drittel Übereinstimmung genügen für einen Punkt im Raum.','Man kann die widersprüchliche Koordinate weglassen.','Die Geradengleichung ist eine Gleichheit von Vektoren.','Eine solche Gleichheit gilt nur komponentenweise vollständig, mit demselben Parameterwert.')
    concept('G33',k+4,'Zwei Richtungsvektoren sind orthogonal, aber die zugehörigen Raumgeraden haben keinen gemeinsamen Punkt. Was ist die präzise Aussage?', 'Die Richtungen stehen senkrecht, die Geraden sind jedoch windschief und haben keinen Schnittpunkt.','Die Geraden schneiden sich zwingend unter 90°.','Die Geraden sind identisch.','Ein Skalarprodukt 0 beurteilt zunächst nur die Richtungen.','Für einen geometrischen Schnittpunkt brauchst du zusätzlich eine erfolgreiche gemeinsame Punktprobe. Richtungswinkel und Schnitt sind verschiedene Informationen.')


def build():
    QUESTIONS.clear();SOLUTIONS.clear();CHECKS.clear()
    analysis();geometry();revisions()
    assert len(QUESTIONS)==396,len(QUESTIONS)
    assert len({q['id'] for q in QUESTIONS})==396
    return QUESTIONS,SOLUTIONS,CHECKS

def revise(qid,prompt,answer,w1,w2,steps):
    q=next(q for q in QUESTIONS if q['id']==qid)
    rotation=(int(q['competency'][1:])+(int(qid[1:])-101)%6+1)%3
    values=[answer,w1,w2];q['prompt']=prompt;q['options']=values[rotation:]+values[:rotation];q['validationStatus']='manually_reviewed'
    SOLUTIONS[qid].update(correct=q['options'].index(answer),steps=steps,explanation=' '.join(steps))
    CHECKS[qid]=dict(status='manually_reviewed',method=dict(kind='editorial',proof=steps),reviewScope='Redaktionelle Begründung geprüft; unabhängige fachliche Freigabe steht aus.')

def revisions():
    revise('A130','Löse über den reellen Zahlen '+m(r'x^4-5x^2+4=0')+'.',m(r'x\in\{-2,-1,1,2\}'),m(r'x\in\{1,2\}'),m(r'x\in\{-1,1\}'),['Setze z = x². Dann lautet die quadratische Gleichung z² − 5z + 4 = 0 mit Lösungen z = 1 und z = 4.','Jeder positive z-Wert liefert zwei x-Werte. Prüfe x = ±1 und x = ±2 in der ursprünglichen Gleichung.'])
    revise('A248','Links von x = 4 ist f(x) = x − 4, rechts und an der Stelle ist f(x) = 2(x − 4). Wie ist der Übergang?','Stetig, aber nicht differenzierbar: Es gibt einen Knick.','Nicht stetig, weil die Formeln verschieden sind.','Differenzierbar, weil beide Seiten den Wert 0 haben.',['Beide einseitigen Grenzwerte und der Funktionswert sind 0, also ist die Funktion stetig.','Links ist die Steigung 1, rechts 2. Weil die einseitigen Ableitungen nicht übereinstimmen, gibt es einen Knick.'])
    revise('A250','Für '+m(r'f_a(x)=x^3-a x')+' wird a = 0 eingesetzt. Warum liegt bei x = 0 kein Extrempunkt vor?','Der Graph steigt beidseits der waagerechten Tangente weiter.','Jede Nullstelle von f′ ist ein Extrempunkt.','Die dritte Potenz hat keine Ableitung.',['Für a = 0 ist f(x) = x³ und f′(x) = 3x². Die Ableitung wird nur an 0 gleich 0.','Das Vorzeichen von f′ wechselt nicht. Die Funktion ist streng steigend; es liegt ein Sattelpunkt statt eines Extrempunkts vor.'])
    revise('A260','Wie groß ist der Funktionsmittelwert von '+m(r'f(x)=2x')+' auf '+m(r'[0;4]')+'?',m(4),m(16),m(8),['Integriere zuerst: Das Integral von 2x von 0 bis 4 beträgt 16.','Teile durch die Intervalllänge 4 − 0 = 4. Der Mittelwert ist 4, nicht das Integral selbst.'])
    # Zweite konzeptionelle Varianten stellen andere Fragen statt identische Sätze zu verdoppeln.
